@test("COOLBET-ODDS-SNAPSHOT — parse_market maps new Coolbet schema to our shape")
def _():
    """COOLBET-ODDS-SNAPSHOT (2026-05-20) — Coolbet API restructured: markets
    + odds now served from separate endpoints. parse_market reads the new
    `{market_type_id, line, outcomes:[{id, result_key}]}` shape and looks
    odds up from a separate {outcome_id: decimal} map. Guards:
      - market_type_id 81 → 1x2 with result_key [Home]/Draw/[Away]
      - market_type_id 818 + line=1.5 → over_under_15 with result_key Over/Under
      - Unknown markets fall back to name-based detection
      - Outcomes missing from odds_map are dropped (no 0-odds rows)
      - AH stores handicap_line from home perspective
    """
    from workers.automation.coolbet_explorer import parse_market

    # 1X2 (market_type_id 81, real Coolbet shape from probe).
    # odds_map values are now dicts ({value, odds_id, ...}) — placer needs odds_id
    # for the placement payload; explorer just reads .value.
    odds = {
        1502758378: {"value": 2.25, "odds_id": "uuid-h", "market_id": 598381104, "status": "OPEN"},
        1502758379: {"value": 3.20, "odds_id": "uuid-d", "market_id": 598381104, "status": "OPEN"},
        1502758380: {"value": 3.10, "odds_id": "uuid-a", "market_id": 598381104, "status": "OPEN"},
    }
    rows = parse_market({
        "id": 598381104, "line": 0, "name": "Match Result (1X2)",
        "market_type_id": 81,
        "outcomes": [
            {"id": 1502758378, "name": "SC Grobinas", "result_key": "[Home]"},
            {"id": 1502758379, "name": "Draw",        "result_key": "Draw"},
            {"id": 1502758380, "name": "SK Super Nova","result_key": "[Away]"},
        ],
    }, odds)
    # COOLBET-SELECTION-CASE (2026-06-03): emit lowercase to match other bookmakers.
    assert rows == [
        ("1x2", "home", 2.25, None),
        ("1x2", "draw", 3.20, None),
        ("1x2", "away", 3.10, None),
    ], f"1X2 parse wrong: {rows}"

    # OU 1.5 (market_type_id 818, line='1.5')
    odds = {
        1502775086: {"value": 1.05, "odds_id": "uuid-o", "market_id": 598387279, "status": "OPEN"},
        1502775087: {"value": 7.00, "odds_id": "uuid-u", "market_id": 598387279, "status": "OPEN"},
    }
    rows = parse_market({
        "id": 598387279, "line": "1.5", "name": "Total Goals Over / Under",
        "market_type_id": 818,
        "outcomes": [
            {"id": 1502775086, "result_key": "Over"},
            {"id": 1502775087, "result_key": "Under"},
        ],
    }, odds)
    assert rows == [
        ("over_under_15", "over", 1.05, None),
        ("over_under_15", "under", 7.00, None),
    ], f"OU 1.5 parse wrong: {rows}"

    # BTTS — falls back to name-based detection (mtid set is still empty)
    odds = {
        9001: {"value": 1.85, "odds_id": "b1", "market_id": 1, "status": "OPEN"},
        9002: {"value": 1.90, "odds_id": "b2", "market_id": 1, "status": "OPEN"},
    }
    rows = parse_market({
        "id": 1, "line": 0, "name": "Both Teams to Score", "market_type_id": 999,
        "outcomes": [
            {"id": 9001, "result_key": "Yes"},
            {"id": 9002, "result_key": "No"},
        ],
    }, odds)
    assert rows == [
        ("btts", "yes", 1.85, None),
        ("btts", "no", 1.90, None),
    ], f"BTTS fallback wrong: {rows}"

    # AH — line is home-perspective; both outcomes share it
    odds = {
        7001: {"value": 1.95, "odds_id": "a1", "market_id": 1, "status": "OPEN"},
        7002: {"value": 1.85, "odds_id": "a2", "market_id": 1, "status": "OPEN"},
    }
    rows = parse_market({
        "id": 1, "line": "-1.25", "name": "Asian Handicap", "market_type_id": 999,
        "outcomes": [
            {"id": 7001, "result_key": "[Home]"},
            {"id": 7002, "result_key": "[Away]"},
        ],
    }, odds)
    assert rows == [
        ("asian_handicap", "home", 1.95, -1.25),
        ("asian_handicap", "away", 1.85, -1.25),
    ], f"AH parse wrong: {rows}"

    # Outcome with no odds entry must be dropped, not stored at 0
    rows = parse_market({
        "id": 1, "line": 0, "name": "Match Result (1X2)", "market_type_id": 81,
        "outcomes": [
            {"id": 1, "result_key": "[Home]"},
            {"id": 2, "result_key": "Draw"},
            {"id": 3, "result_key": "[Away]"},
        ],
    }, {1: {"value": 2.0, "odds_id": "x", "market_id": 1, "status": "OPEN"}})  # only home
    assert rows == [("1x2", "home", 2.0, None)], (
        f"missing odds must drop, not zero-fill: {rows}"
    )

    # Scheduler registration
    import pathlib
    src = pathlib.Path("workers/scheduler.py").read_text()
    assert "_coolbet_odds_snapshot_wrapper" in src, "missing wrapper function"
    assert "coolbet_odds_interval" in src, "missing coolbet_odds_interval job id"
    assert '"3,33"' in src, "Coolbet snapshot must fire at :03 and :33"

    # Endpoint constants must exist (used by the new fetcher)
    explorer_src = pathlib.Path("workers/automation/coolbet_explorer.py").read_text()
    assert "_ODDS_LINE_URL" in explorer_src, "missing /fo-line/ URL constant"
    assert "fetch_match_markets" in explorer_src, "missing fetch_match_markets"
    assert "fetch_odds_for_markets" in explorer_src, "missing fetch_odds_for_markets"


@test("COOLBET-HUMAN-PACED — every CoolbetSession call routes through _throttle()")
def _():
    """COOLBET-HUMAN-PACED (2026-05-20) — Coolbet has Imperva-class anti-bot
    in front of the API. Every authenticated call must go through _throttle()
    which enforces a randomised gap (default 0.8–2.0s) between consecutive
    requests so we don't look like a scraper. Centralised in CoolbetSession so
    new daemon/scheduler/explorer features can't bypass it accidentally."""
    import inspect
    from workers.automation.coolbet_session import CoolbetSession
    assert hasattr(CoolbetSession, "_throttle"), "missing _throttle()"
    get_src = inspect.getsource(CoolbetSession.get)
    post_src = inspect.getsource(CoolbetSession.post)
    assert "self._throttle()" in get_src, "get() must call _throttle"
    assert "self._throttle()" in post_src, "post() must call _throttle"
    src = inspect.getsource(CoolbetSession._throttle)
    assert "random.uniform" in src, "_throttle must use jitter (random.uniform), not constant gap"


@test("COOLBET-PLACER-NEW-SCHEMA — resolve_placement_target + placer wired to new helpers")
def _():
    """COOLBET-PLACER-NEW-SCHEMA (2026-05-20) — Coolbet split markets and odds
    into separate endpoints and dropped `criterion_label`. resolve_placement_target
    maps our paper-bet (market, selection) → Coolbet (market_id, outcome_id,
    odds_id, current_odds) using the new markets/outcomes/result_key/line shape.
    place_all_bets's per-bet loop must use the new helpers, not the dead
    find_market_outcome path."""
    from workers.automation.coolbet_explorer import resolve_placement_target

    # 1X2 Home — full real-shape sample from probe
    markets = [{
        "id": 598381104, "line": 0, "name": "Match Result (1X2)",
        "market_type_id": 81,
        "outcomes": [
            {"id": 1502758378, "result_key": "[Home]"},
            {"id": 1502758379, "result_key": "Draw"},
            {"id": 1502758380, "result_key": "[Away]"},
        ],
    }]
    odds = {
        1502758378: {"value": 2.25, "odds_id": "uuid-h", "market_id": 598381104, "status": "OPEN"},
        1502758379: {"value": 3.20, "odds_id": "uuid-d", "market_id": 598381104, "status": "OPEN"},
        1502758380: {"value": 3.10, "odds_id": "uuid-a", "market_id": 598381104, "status": "OPEN"},
    }
    res = resolve_placement_target(markets, odds, "1X2", "Home")
    assert res == (598381104, 1502758378, "uuid-h", 2.25), f"1X2 Home wrong: {res}"

    res = resolve_placement_target(markets, odds, "1X2", "Draw")
    assert res == (598381104, 1502758379, "uuid-d", 3.20), f"1X2 Draw wrong: {res}"

    # OU 1.5 Over
    markets = [{
        "id": 598387279, "line": "1.5", "name": "Total Goals Over / Under",
        "market_type_id": 818,
        "outcomes": [
            {"id": 1502775086, "result_key": "Over"},
            {"id": 1502775087, "result_key": "Under"},
        ],
    }]
    odds = {
        1502775086: {"value": 1.05, "odds_id": "uuid-o", "market_id": 598387279, "status": "OPEN"},
        1502775087: {"value": 7.00, "odds_id": "uuid-u", "market_id": 598387279, "status": "OPEN"},
    }
    res = resolve_placement_target(markets, odds, "O/U", "Over 1.5")
    assert res == (598387279, 1502775086, "uuid-o", 1.05), f"OU Over 1.5 wrong: {res}"

    # OU line mismatch — same market, different line — must return None
    res = resolve_placement_target(markets, odds, "O/U", "Over 2.5")
    assert res is None, f"OU line mismatch must return None, got {res}"

    # Outcome with no odds entry → None (suspended / dropped)
    res = resolve_placement_target(markets, {}, "O/U", "Over 1.5")
    assert res is None, f"empty odds_map must return None, got {res}"

    # AH home -1.25
    markets = [{
        "id": 1, "line": "-1.25", "name": "Asian Handicap", "market_type_id": 999,
        "outcomes": [
            {"id": 7001, "result_key": "[Home]"},
            {"id": 7002, "result_key": "[Away]"},
        ],
    }]
    odds = {
        7001: {"value": 1.95, "odds_id": "ah1", "market_id": 1, "status": "OPEN"},
        7002: {"value": 1.85, "odds_id": "ah2", "market_id": 1, "status": "OPEN"},
    }
    res = resolve_placement_target(markets, odds, "asian_handicap", "Home -1.25")
    assert res == (1, 7001, "ah1", 1.95), f"AH home wrong: {res}"

    # AH line mismatch
    res = resolve_placement_target(markets, odds, "asian_handicap", "Home -1.5")
    assert res is None, f"AH line mismatch must return None, got {res}"

    # Placer per-bet loop wiring
    import pathlib
    placer = pathlib.Path("workers/automation/coolbet_placer.py").read_text()
    assert "from workers.automation.coolbet_explorer import" in placer, (
        "placer must import the new-schema helpers from coolbet_explorer"
    )
    assert "resolve_placement_target" in placer, "placer must call resolve_placement_target"
    assert "fetch_match_markets" in placer, "placer must call fetch_match_markets"
    assert "fetch_odds_for_markets" in placer, "placer must call fetch_odds_for_markets"
    # Make sure the per-bet loop no longer relies on criterion_label
    # (legacy find_market_outcome may still exist for back-compat but must not
    # be in the active placement path).
    in_place_all = placer[placer.index("def place_all_bets"):]
    # Comments referencing the old field are fine; what's forbidden is
    # actually accessing it as a dict key, since the new schema has no such field.
    assert 'bo["criterion_label"]' not in in_place_all, (
        "place_all_bets must not read bo['criterion_label'] — field doesn't exist on new schema"
    )
    assert 'bo[\'criterion_label\']' not in in_place_all, (
        "place_all_bets must not read bo['criterion_label'] — field doesn't exist on new schema"
    )


@test("COOLBET-SEARCH-BLOCKED — non-200 raises, placer aborts loop, summary names it")
def test_coolbet_search_blocked():
    """COOLBET-SEARCH-BLOCKED (2026-05-26): a dead cbauth JWT or Incapsula
    challenge returns 4xx/5xx from /search/v2. Previously swallowed at DEBUG,
    making 18 doomed searches look like 18 genuine no-coverage misses. The
    placer now raises CoolbetSearchBlocked, marks the current + remaining
    bets as 'search_blocked', and skips the combo phase."""
    import inspect, pathlib

    # Module-level exception is exported
    from workers.automation.coolbet_placer import CoolbetSearchBlocked  # noqa: F401

    placer_src = pathlib.Path("workers/automation/coolbet_placer.py").read_text()

    # _do_search must raise (not swallow) on non-200
    do_search = placer_src[placer_src.index("def _do_search"):
                            placer_src.index("def search_coolbet_event")]
    assert "raise CoolbetSearchBlocked" in do_search, (
        "_do_search must raise CoolbetSearchBlocked on non-200, not return []"
    )
    assert "log.warning" in do_search, (
        "_do_search must log non-200 at WARNING (not DEBUG) so blocks are visible"
    )

    # Singles loop must catch + mark remaining bets as search_blocked + break
    in_place_all = placer_src[placer_src.index("def place_all_bets"):]
    singles_catch = in_place_all[:in_place_all.index("_place_combo_bets") + 200]
    assert "except CoolbetSearchBlocked" in singles_catch, (
        "singles loop must catch CoolbetSearchBlocked"
    )
    assert '"outcome": "search_blocked"' in singles_catch, (
        "blocked bet rows must use outcome='search_blocked' (not 'no_event')"
    )
    assert "pending[idx:]" in singles_catch, (
        "remaining unprocessed bets must be marked as search_blocked, not silently dropped"
    )

    # Combo phase is skipped when singles loop tripped the block
    assert "if search_blocked:" in singles_catch, (
        "place_all_bets must skip combo phase when singles tripped the block"
    )

    # Combo loop has matching handling
    combo_src = placer_src[placer_src.index("def _place_combo_bets"):]
    assert "except CoolbetSearchBlocked" in combo_src, (
        "combo loop must also catch CoolbetSearchBlocked"
    )
    assert "combos[cidx:]" in combo_src, (
        "remaining combos must be marked as search_blocked on mid-run block"
    )

    # CLI summary surfaces the block prominently
    cli_src = pathlib.Path("scripts/place_coolbet_bets.py").read_text()
    assert "search_blocked" in cli_src, (
        "place_coolbet_bets.py summary must recognise search_blocked outcome"
    )
    assert "COOLBET_MANUAL_JWT" in cli_src, (
        "CLI must tell user how to fix it (refresh COOLBET_MANUAL_JWT)"
    )


@test("COOLBET-FS-SESSION-STABLE — hybrid FS transport (GET via FS, POST via requests + FS cookies)")
def _():
    """COOLBET-FS-SESSION-STABLE (2026-06-11): the previous CoolbetSession
    used a plain requests.Session, which got 403/500'd by Imperva because
    its TLS fingerprint didn't match a real browser. Routing GETs via FS
    fixes that. BUT — FlareSolverr force-encodes POST bodies as
    application/x-www-form-urlencoded and truncates JSON to ~4 bytes
    (verified 2026-06-11 via httpbin echo). So we can't naively route
    POSTs via FS either.

    Hybrid architecture (the one that actually works):
      - GET  → FlareSolverr (real Chrome TLS, full Imperva pass)
      - POST → plain requests.Session WITH cookies harvested from a
        FS GET. Imperva accepts the cookies (they were issued to FS's
        Chrome), and plain requests properly sends JSON bodies.

    This pin locks the architectural invariant so a future refactor
    doesn't silently regress to either pure-FS (breaks JSON POST) or
    pure-requests (Imperva blocks the TLS fingerprint).
    """
    import pathlib
    src = pathlib.Path("workers/automation/coolbet_session.py").read_text()

    # FS helpers (still needed for GETs + cookie harvest)
    assert "def _fs_call(" in src, "Module-level _fs_call(body) helper required"
    assert "def _fs_session_ensure(" in src, "Module-level _fs_session_ensure required"
    assert "class _FSResponse:" in src, "_FSResponse adapter required for GET path"
    for attr in ("status_code", "text", "ok", "json", "raise_for_status", "cookies"):
        assert attr in src.split("class _FSResponse")[1].split("\nclass ")[0], (
            f"_FSResponse must expose {attr} to stay drop-in-compatible with "
            f"requests.Response."
        )

    # Cookie harvest: the critical bridge between FS-issued cookies and
    # plain-requests POST. Without this method, POSTs hit Imperva with
    # whatever stale cookies happened to be in self._http.
    assert "def _refresh_cookies_from_fs(" in src, (
        "_refresh_cookies_from_fs() method required — harvests Imperva "
        "cookies + UA from FS browser into self._http for POST."
    )
    refresh_block = src.split("def _refresh_cookies_from_fs(")[1].split("\n    def ")[0]
    assert "self._http.cookies.clear()" in refresh_block, (
        "Cookie harvest must wipe stale cookies before copying fresh ones — "
        "Imperva rotates; preserving expired cookies risks re-challenge."
    )
    assert "reese84" in refresh_block, (
        "Cookie harvest must specifically validate (or log) reese84 presence "
        "— it's Imperva's primary challenge token."
    )

    # GET: routes via FS (real Chrome).
    get_block = src.split("    def get(self, url: str, **kwargs)")[1].split("    def ")[0]
    assert "self._fs_get(" in get_block, "CoolbetSession.get must route via FS"
    assert "self._http.get(" not in get_block, (
        "CoolbetSession.get must NOT use self._http.get — that's the plain-"
        "requests path Imperva blocks for GETs."
    )

    # POST: routes via plain requests, requires fresh FS-harvested cookies.
    post_block = src.split("    def post(self, url: str, **kwargs)")[1].split("    def ")[0]
    assert "self._http.post(" in post_block, (
        "CoolbetSession.post must use self._http.post (plain requests) — "
        "FlareSolverr can't send JSON bodies properly."
    )
    assert "_refresh_cookies_from_fs(" in post_block, (
        "CoolbetSession.post must call _refresh_cookies_from_fs() (directly "
        "or via the _cookies_fresh guard) so FS-issued cookies are present "
        "before the plain-requests POST."
    )
    # Auto-retry on 401/403 — Imperva cookies expire fast; refresh+retry once.
    assert "401" in post_block and "403" in post_block, (
        "CoolbetSession.post must check for 401/403 status and retry once "
        "after refreshing cookies."
    )

    # _login + renew_jwt_via_api also POST JSON → must use plain requests.
    login_block = src.split("    def _login(")[1].split("\n    def ")[0]
    assert "self._http.post(_LOGIN_URL" in login_block, (
        "_login must use plain self._http.post (FS can't send JSON login body)."
    )
    renew_block = src.split("    def renew_jwt_via_api(")[1].split("\n    def ")[0]
    assert "self._http.post(_RENEW_URL" in renew_block, (
        "renew_jwt_via_api must use plain self._http.post."
    )

    # Default FS session name is coolbet_prod (production-scoped).
    assert 'COOLBET_FLARE_SESSION", "coolbet_prod"' in src, (
        "Default FS session name must be coolbet_prod."
    )


@test("COOLBET-FS-SESSION-OBSERVABLE — session state writes + heartbeat + sweeper")
def _():
    """COOLBET-FS-SESSION-STABLE Step 1.3 + 1.5 (2026-06-11): the auth chain
    isn't operationally useful unless we can see its state. This pin:
      - asserts the singleton state table exists (migration 242)
      - asserts CoolbetSession writes to it on login + cookie refresh
      - asserts the heartbeat + sweeper scripts exist and are scheduled
    """
    import pathlib, ast
    # Migration 242 creates the state table with the singleton + trigger.
    mig = pathlib.Path("supabase/migrations/242_coolbet_session_state.sql").read_text()
    assert "CREATE TABLE IF NOT EXISTS coolbet_session_state" in mig, (
        "Migration 242 must CREATE TABLE IF NOT EXISTS coolbet_session_state."
    )
    assert "CONSTRAINT singleton_row CHECK (id = 1)" in mig, (
        "State table must be a singleton (CHECK id=1) — multiple rows would "
        "be ambiguous for /status to display."
    )

    # State writer helpers exist with the right shape.
    state_src = pathlib.Path("workers/automation/coolbet_state.py").read_text()
    for fn in ("mark_login_success", "mark_error", "mark_heartbeat",
                "mark_cookies_refreshed", "read_state"):
        assert f"def {fn}(" in state_src, (
            f"coolbet_state.py must expose {fn}() — used by session class + "
            f"future Telegram /status command."
        )

    # CoolbetSession wires those into its login + cookie-refresh paths.
    sess_src = pathlib.Path("workers/automation/coolbet_session.py").read_text()
    assert "_state().mark_login_success(" in sess_src, (
        "CoolbetSession must call mark_login_success on every successful "
        "JWT adoption (both manual_jwt and api_login paths)."
    )
    assert "_state().mark_cookies_refreshed(" in sess_src, (
        "_refresh_cookies_from_fs must call mark_cookies_refreshed so "
        "/admin pages can see when cookies last rotated."
    )

    # Heartbeat + sweeper scripts exist.
    assert pathlib.Path("scripts/coolbet/health_ping.py").exists(), (
        "scripts/coolbet/health_ping.py required (the heartbeat cron)."
    )
    assert pathlib.Path("scripts/coolbet/sweep_stale_sessions.py").exists(), (
        "scripts/coolbet/sweep_stale_sessions.py required (the sweeper cron)."
    )

    # Scheduler registers both crons.
    sched = pathlib.Path("workers/scheduler.py").read_text()
    tree = ast.parse(sched)
    fns = {n.name for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)}
    assert "job_coolbet_health_ping" in fns, "scheduler must define job_coolbet_health_ping"
    assert "job_flaresolverr_sweep" in fns, "scheduler must define job_flaresolverr_sweep"
    ids = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Call) and getattr(n.func, "attr", "") == "add_job":
            for kw in n.keywords:
                if kw.arg == "id" and isinstance(getattr(kw.value, "value", None), str):
                    ids.add(kw.value.value)
    assert "coolbet_health_ping" in ids, "coolbet_health_ping cron must be registered"
    assert "flaresolverr_sweep" in ids, "flaresolverr_sweep cron must be registered"


@test("COOLBET-JWT-DB-BACKED — JWT bootstraps from coolbet_session_state, persists on every login/renew")
def test_coolbet_jwt_db_backed():
    """COOLBET-JWT-DB-BACKED (2026-06-12): Imperva 403's /s/auth/login from
    cloud IPs (Railway) but accepts it from residential IPs (local). Before
    this change, Railway lost its session on every restart and the operator
    had to paste a fresh JWT to COOLBET_MANUAL_JWT env every time something
    broke — env-var drift between local and Railway was a recurring failure
    mode.

    The fix: persist the JWT to coolbet_session_state.jwt_current after
    every successful login/renew. CoolbetSession bootstraps from that
    column on init, falling back to env var only when DB is empty. Local
    enrollment (residential IP) writes to DB → Railway reads from DB on
    next process start → keeps it alive via /s/auth/renew-token (which
    Imperva accepts from any IP).

    Pin the contract so a future refactor can't quietly remove the
    persistence hooks and leave us back at env-var drift."""
    import pathlib
    # Migration 245 adds the column + tightens RLS.
    mig = pathlib.Path("supabase/migrations/245_coolbet_jwt_persistent.sql").read_text()
    assert "ADD COLUMN IF NOT EXISTS jwt_current TEXT" in mig, (
        "Migration 245 must add jwt_current TEXT to coolbet_session_state."
    )
    assert "DROP POLICY IF EXISTS coolbet_session_state_anon_read" in mig, (
        "Migration 245 must drop the open-anon SELECT policy — jwt_current "
        "is sensitive auth material and must not be readable via anon key."
    )

    # State helpers exist.
    state_src = pathlib.Path("workers/automation/coolbet_state.py").read_text()
    assert "def persist_jwt(" in state_src, (
        "coolbet_state must expose persist_jwt() — called after every successful "
        "adopt/api_login/renew to update the canonical store."
    )
    assert "def read_persisted_jwt(" in state_src, (
        "coolbet_state must expose read_persisted_jwt() — used by CoolbetSession "
        "to bootstrap from DB."
    )

    # CoolbetSession bootstraps from DB AND persists on success.
    sess_src = pathlib.Path("workers/automation/coolbet_session.py").read_text()
    assert "read_persisted_jwt" in sess_src, (
        "CoolbetSession.__init__ must read_persisted_jwt() so Railway can "
        "inherit the JWT after local enrollment without an env-var push."
    )
    assert "_pick_freshest_jwt(" in sess_src, (
        "CoolbetSession must compare env-JWT vs DB-JWT and pick the one with "
        "the later exp claim — bootstrap order matters."
    )
    # Persist hooks fire on both successful paths.
    adopt_block = sess_src[
        sess_src.index("def _adopt_manual_jwt("):
        sess_src.index("def renew_jwt_via_api(")
    ]
    assert 'persist_jwt(token' in adopt_block, (
        "_adopt_manual_jwt must persist the JWT to DB so a session bootstrapped "
        "from env-var ALSO updates DB — keeps both sources convergent."
    )
    login_block = sess_src[
        sess_src.index("def _login("):
        sess_src.index("def _ensure_auth(")
    ]
    assert 'persist_jwt(token' in login_block, (
        "_login (API login path) must persist the JWT to DB so a successful "
        "local API login propagates to Railway via DB."
    )

    # Enrollment writes to DB (this is THE bootstrap path for Railway).
    enroll_src = pathlib.Path("scripts/coolbet/flaresolverr_login_enroll.py").read_text()
    assert "from workers.automation.coolbet_state import persist_jwt" in enroll_src, (
        "flaresolverr_login_enroll.py must import persist_jwt from coolbet_state — "
        "this is the ONLY entrypoint that gets a fresh JWT past Imperva from a "
        "Railway-blocked context. Without DB write, Railway never inherits."
    )
    # Tagged so /status can show where the latest JWT came from.
    assert 'set_by="local_enroll"' in enroll_src, (
        'Enrollment must tag set_by="local_enroll" — distinguishes the SMS-trust '
        "bootstrap from in-process renewals in observability."
    )


@test("COOLBET-MAC-DAEMON — local Mac placement daemon + launchd + local FS")
def test_coolbet_mac_daemon():
    """COOLBET-MAC-DAEMON (2026-06-12): option B of the signaler/daemon
    architecture. Mac at home runs the placement leg from a residential IP
    so Imperva's cloud-IP block doesn't apply. Pin the deployable artifacts
    so a future refactor can't quietly remove one half of the setup."""
    import pathlib
    # Daemon module exists with the right entrypoints.
    daemon_src = pathlib.Path("workers/automation/coolbet_mac_daemon.py").read_text()
    for fn in ("_tick", "run_forever", "main"):
        assert f"def {fn}(" in daemon_src, f"daemon must expose {fn}()"
    # Daemon calls the existing placer (NOT a fork) — same edge gates,
    # same idempotency guarantees as the Railway-side implementation
    # we just shelved. Drift here is the failure mode this test prevents.
    assert "from workers.automation.coolbet_placer import" in daemon_src, (
        "daemon must call the existing coolbet_placer — no fork of placement logic."
    )
    # CONTRACT (not literal syntax): daemon production path must call
    # place_all_bets with record=True. record=False is only acceptable in
    # the dry-run branch (which also forces execute=False). The original
    # literal `place_all_bets(record=True, execute=not dry_run)` was
    # refactored 2026-06 into an if/else with separate calls.
    assert "place_all_bets(record=True, execute=True)" in daemon_src, (
        "daemon production path must call place_all_bets(record=True, execute=True) — "
        "record always so real_bets gets a row."
    )
    assert "place_all_bets(record=False, execute=False)" in daemon_src, (
        "daemon dry-run path must call place_all_bets(record=False, execute=False) — "
        "no DB writes when invoked with --dry-run."
    )
    # SIGTERM handler — must not crash the daemon on launchd shutdown.
    assert "signal.SIGTERM" in daemon_src and "signal.SIGINT" in daemon_src, (
        "daemon must trap SIGTERM/SIGINT for graceful launchd shutdown."
    )

    # docker-compose for local FS exists with a persistent volume —
    # without the volume, tab-crash + container-restart loses device trust.
    fs_compose = pathlib.Path("local/flaresolverr/docker-compose.yml").read_text()
    assert "flaresolverr_profile:/app/profiles" in fs_compose, (
        "docker-compose must mount a persistent profile volume — without "
        "it, every restart loses Chrome's device-trust cookie."
    )
    assert "restart: unless-stopped" in fs_compose, (
        "FS container must auto-restart so a crash doesn't leave the "
        "daemon talking to a dead endpoint."
    )

    # launchd plist exists and references the daemon module.
    plist = pathlib.Path("local/launchd/com.oddsintel.coolbet-mac-daemon.plist").read_text()
    assert "workers.automation.coolbet_mac_daemon" in plist, (
        "launchd plist must invoke the daemon via -m workers.automation.coolbet_mac_daemon"
    )
    assert "<key>KeepAlive</key>" in plist and "<true/>" in plist, (
        "launchd must KeepAlive — daemon auto-restart is the supervisor."
    )
    # Local FS URL override so daemon doesn't accidentally hit Railway FS
    # (defeats the residential-IP premise).
    assert "http://localhost:8191" in plist, (
        "plist must pin FLARESOLVERR_URL=http://localhost:8191 — Railway FS "
        "doesn't help us from the Mac; the whole point is using local."
    )

    # Setup README exists so the operator has a single source for the
    # one-time install sequence.
    readme = pathlib.Path("local/README.md")
    assert readme.exists(), "local/README.md is the operator's setup guide"
    rt = readme.read_text()
    for step in ("docker compose up", "flaresolverr_login_enroll.py",
                  "launchctl load", "--once --dry-run"):
        assert step in rt, f"README must document step: {step!r}"


@test("COOLBET-SIGNALER-A — Telegram bet-signaler replaces auto-placer (resilient to Imperva/FS)")
def test_coolbet_signaler():
    """COOLBET-SIGNALER-A (2026-06-12): the auto-place chain (Imperva 403 from
    Railway IPs → FlareSolverr Chrome tab → 30-min JWT TTL → SMS-2FA on
    re-login) was structurally fragile and spammed SMS overnight. Signal-only
    mode is the safety net: pure DB read + Telegram send, zero Coolbet API.

    Pin the contract so a future refactor can't quietly reintroduce the
    auto-placer in the pipeline path."""
    import pathlib
    mig246 = pathlib.Path("supabase/migrations/246_simulated_bets_signaled_at.sql").read_text()
    assert "ADD COLUMN IF NOT EXISTS signaled_at TIMESTAMPTZ" in mig246, (
        "Mig 246 must add signaled_at TIMESTAMPTZ to simulated_bets — the "
        "only thing preventing the signaler from spamming the same bet."
    )
    mig247 = pathlib.Path("supabase/migrations/247_matches_coolbet_match_id.sql").read_text()
    assert "ADD COLUMN IF NOT EXISTS coolbet_match_id BIGINT" in mig247, (
        "Mig 247 must add coolbet_match_id BIGINT to matches — cached "
        "deep-link target so signals carry a direct match-page URL."
    )
    sig_src = pathlib.Path("workers/automation/coolbet_signaler.py").read_text()
    for fn in ("load_signal_candidates", "_format_signal", "_mark_signaled",
                "_resolve_coolbet_match_id", "signal_all_bets"):
        assert f"def {fn}(" in sig_src, f"coolbet_signaler must expose {fn}()"
    assert "from workers.automation.coolbet_placer import _min_edge_for, _MIN_EDGE" in sig_src, (
        "signaler must reuse _min_edge_for + _MIN_EDGE from the placer so "
        "per-market floors stay in lock-step."
    )
    mark_block = sig_src[sig_src.index("def _mark_signaled("):sig_src.index("def signal_all_bets(")]
    assert "WHERE match_id" in mark_block and "AND market" in mark_block and "AND selection" in mark_block, (
        "_mark_signaled must mark ALL rows for (match,market,selection), not "
        "just the canonical row — else sibling bot picks re-fire next run."
    )
    pipe_src = pathlib.Path("workers/jobs/betting_pipeline.py").read_text()
    assert "def _run_coolbet_signal(" in pipe_src, (
        "betting_pipeline must define _run_coolbet_signal."
    )
    assert "_run_coolbet_signal()" in pipe_src, (
        "run_betting() must call _run_coolbet_signal()"
    )
    assert "place_all_bets(record=True" not in pipe_src, (
        "betting_pipeline must NOT call place_all_bets — SMS-spam risk. "
        "Use the signaler instead."
    )


@test("COOLBET-NO-AUTO-LOGIN — heartbeat/placement/scanner refuse /s/auth/login by default")
def test_coolbet_no_auto_login():
    """COOLBET-NO-AUTO-LOGIN (2026-06-12): on 2026-06-11 evening the
    heartbeat cron triggered 100+ SMS 2FA messages overnight. Root cause:
    JWT expired, every 5-min heartbeat called _ensure_auth → _login →
    /s/auth/login. Coolbet sent SMS each time because Railway IP wasn't
    device-trusted. Account lockout risk.

    The fix: CoolbetSession() refuses API login by default. Only the
    enrollment script (deliberately operator-initiated) sets
    allow_api_login=True. All other contexts — heartbeat, placement,
    scanner — read DB JWT and fail fast if expired, surfacing "re-enroll"
    in /status instead of bombing the operator with SMS.

    Pin the default + the bypass so a future refactor can't remove the
    guard."""
    import pathlib, inspect, ast
    from workers.automation.coolbet_session import CoolbetSession

    sig = inspect.signature(CoolbetSession.__init__)
    assert "allow_api_login" in sig.parameters, (
        "CoolbetSession.__init__ must take allow_api_login parameter — the "
        "guard that prevents SMS spam from unattended JWT-expiry retries."
    )
    default = sig.parameters["allow_api_login"].default
    assert default is None, (
        f"allow_api_login default must be None (so env-var override kicks in); got {default!r}"
    )

    src = pathlib.Path("workers/automation/coolbet_session.py").read_text()
    # _login refuses to fall through unless explicitly opted in.
    login_block = src[src.index("def _login("):src.index("def _ensure_auth(")]
    assert "self._allow_api_login" in login_block, (
        "_login must gate on self._allow_api_login — both the expired-JWT "
        "fall-through AND the no-JWT path."
    )
    assert "SMS-2FA spam" in login_block, (
        "_login must surface the WHY in its RuntimeError so future debug "
        "doesn't reintroduce the loop (the comment is part of the contract)."
    )

    # Enrollment script opts in (it's the only context that should).
    enroll_src = pathlib.Path("scripts/coolbet/flaresolverr_login_enroll.py").read_text()
    assert 'COOLBET_ALLOW_API_LOGIN' in enroll_src and 'true' in enroll_src.split('COOLBET_ALLOW_API_LOGIN')[1][:100], (
        "Enrollment script must set COOLBET_ALLOW_API_LOGIN=true so it can "
        "actually call /s/auth/login. Without this opt-in the script itself "
        "would be blocked by its own guard."
    )


@test("COOLBET-CDP-JWT-EXTRACT — _login tries CDP-Chrome localStorage before raising SMS-error")
def test_coolbet_cdp_jwt_extract():
    """COOLBET-CDP-JWT-EXTRACT (2026-06-12): CoolbetSession._login() must try
    extracting a fresh JWT from CDP-Chrome's localStorage before raising the
    "JWT expired AND api_login disabled" error.

    Why: Coolbet's frontend auto-renews the JWT every ~20 min while a
    coolbet.com tab is open. As long as the operator's CDP-Chrome
    (--remote-debugging-port=9222) has even one Coolbet tab loaded,
    localStorage['cbauth'] always has a fresh Bearer. Reading it replaces
    BOTH the stale env-paste workflow AND the SMS-triggering /s/auth/login.

    The 2026-06-11 SMS-spam emergency was the breaking point — the daemon
    looped on expired JWT → /s/auth/login → SMS, 100+ times overnight. The
    CDP-JWT path eliminates that loop entirely while keeping the SMS guard
    intact (CDP is tried, not bypassed; SMS path still requires explicit
    allow_api_login=true).

    Pin: extract_jwt_from_cdp + refresh_jwt_via_cdp exist in browser_sync,
    _login calls _try_cdp_jwt before raising the SMS error, and the
    --refresh-jwt CLI is wired."""
    import pathlib
    bs = pathlib.Path("workers/automation/coolbet_browser_sync.py").read_text()
    assert "def extract_jwt_from_cdp(" in bs, (
        "browser_sync must export extract_jwt_from_cdp() — the function that "
        "reads localStorage['cbauth'] from the CDP-Chrome session."
    )
    assert "def refresh_jwt_via_cdp(" in bs, (
        "browser_sync must export refresh_jwt_via_cdp() — operator entrypoint "
        "that persists the extracted JWT to coolbet_session_state and "
        "optionally clears placement_paused."
    )
    assert "localStorage.getItem" in bs and "localStorage.length" in bs, (
        "extract_jwt_from_cdp must read both probe keys and scan all localStorage "
        "keys (defensive against Coolbet renaming the slot)."
    )
    assert "cbauth" in bs, (
        "Known localStorage key 'cbauth' must be in the probe list (verified "
        "2026-06-12 as the slot Coolbet's frontend writes the renewed JWT to)."
    )

    sess = pathlib.Path("workers/automation/coolbet_session.py").read_text()
    assert "def _try_cdp_jwt(" in sess, (
        "coolbet_session must define _try_cdp_jwt() — the bridge that adopts "
        "a CDP-extracted JWT into the session."
    )
    login_block = sess[sess.index("def _login("):sess.index("def _ensure_auth(")]
    assert "_try_cdp_jwt" in login_block, (
        "_login() must call _try_cdp_jwt() — without this, expired-JWT scenarios "
        "skip the silent CDP self-heal and go straight to the SMS-blocked raise."
    )
    # CDP try happens on BOTH expired-JWT and no-JWT branches.
    assert login_block.count("self._try_cdp_jwt()") >= 2, (
        "_login() must try CDP both when manual_jwt is expired AND when there's "
        "no manual_jwt at all (cold boot). Found < 2 _try_cdp_jwt() calls."
    )
    # The SMS-spam guard message is preserved (the existing NO-AUTO-LOGIN
    # contract). We just gate it behind the CDP attempt.
    assert "SMS-2FA spam" in login_block, (
        "_login must still surface 'SMS-2FA spam' in its RuntimeError — the "
        "SMS guard contract from COOLBET-NO-AUTO-LOGIN remains in force."
    )

    # CLI is wired.
    assert "--refresh-jwt" in bs, (
        "browser_sync main() must accept --refresh-jwt so the operator can "
        "trigger a manual JWT pull from CDP after CDP-Chrome restart / login."
    )


@test("COOLBET-DAEMON-ALERTS — daemon pushes Telegram on N consecutive failed ticks with CDP diagnosis")
def test_coolbet_daemon_alerts():
    """COOLBET-DAEMON-ALERTS (2026-06-16): On 2026-06-15/16 the Mac daemon
    errored on 40+ consecutive ticks (~24h) with zero alerts — JWT expired
    AND CDP-Chrome was logged out. One calibrated-bot pick was missed.

    The fix: on the N-th consecutive error tick the daemon classifies the
    underlying CDP state via diagnose_cdp_jwt_state() and pushes a Telegram
    with an actionable recovery hint. Dedup per hour-of-day so a sustained
    outage alerts at most once/hour, not every 30 min.

    Pin: diagnose helper exists with the 5 documented states; daemon
    imports + invokes it; consecutive-error tracking + reset-on-ok
    semantics are in run_forever; Telegram send uses the documented
    dedup-key prefix."""
    import pathlib

    bs = pathlib.Path("workers/automation/coolbet_browser_sync.py").read_text()
    assert "def diagnose_cdp_jwt_state(" in bs, (
        "browser_sync must export diagnose_cdp_jwt_state() — the classifier "
        "that lets the daemon tell the operator WHY placement is failing."
    )
    for state in ("chrome_down", "no_coolbet_tab", "logged_out",
                  "jwt_expired", "valid"):
        assert state in bs, (
            f"diagnose_cdp_jwt_state must produce state='{state}' — the "
            "Telegram recovery hint table relies on this set."
        )
    # The diagnose helper must read CDP read-only (no new tab) — diagnosis
    # must not flash the operator's Chrome window.
    diag_block = bs[bs.index("def diagnose_cdp_jwt_state("):
                    bs.index("def _try_read_localStorage_via_cdp(")]
    assert "allow_open_new_tab=False" in diag_block, (
        "diagnose_cdp_jwt_state must call CDP with allow_open_new_tab=False; "
        "opening a new tab during diagnosis would flash Chrome unexpectedly."
    )

    daemon = pathlib.Path("workers/automation/coolbet_mac_daemon.py").read_text()
    assert "def _notify_consecutive_failures(" in daemon, (
        "Mac daemon must define _notify_consecutive_failures() — the path "
        "that pushes the Telegram alert when error streaks hit threshold."
    )
    assert "diagnose_cdp_jwt_state" in daemon, (
        "Mac daemon must import + call diagnose_cdp_jwt_state() to classify "
        "the failure before alerting — without classification, the operator "
        "still has to tail the log to know what's broken."
    )
    assert "ALERT_AFTER_CONSECUTIVE_ERRORS" in daemon, (
        "Mac daemon must expose ALERT_AFTER_CONSECUTIVE_ERRORS (env-tunable) "
        "so the threshold can be raised on noisy networks without a redeploy."
    )
    # Dedup key MUST exist and MUST be hour-scoped — without an hour bucket,
    # the in-process _LAST_SENT dict would suppress every alert after the
    # first for the lifetime of the process (could be days).
    assert "daemon-fail-burst-" in daemon, (
        "Telegram alert must use dedup_key prefix 'daemon-fail-burst-' so "
        "send_telegram's _LAST_SENT can dedup across ticks."
    )
    # The dedup key in the daemon must include an hour component (%H) so a
    # sustained outage still produces ~one alert per hour.
    notify_block = daemon[daemon.index("def _notify_consecutive_failures("):
                          daemon.index("def _handle_sigterm(")]
    assert "%Y%m%d%H" in notify_block or '"%H"' in notify_block, (
        "Telegram dedup key must include hour-of-day — without an hour bucket "
        "a multi-day outage would alert only once per process restart."
    )

    # The run_forever loop must (a) track consecutive errors, (b) reset on
    # clean ticks, and (c) call _notify_consecutive_failures on threshold.
    loop_block = daemon[daemon.index("def run_forever("):]
    assert "consecutive_errors" in loop_block, (
        "run_forever must maintain a consecutive_errors counter."
    )
    assert "_notify_consecutive_failures(" in loop_block, (
        "run_forever must call _notify_consecutive_failures on the streak threshold."
    )
    # Reset-on-ok: a recovered daemon must NOT keep alerting next streak.
    assert "consecutive_errors = 0" in loop_block, (
        "run_forever must reset consecutive_errors on a clean tick — "
        "otherwise a recovered daemon stays armed and a single later blip "
        "would re-alert at threshold=1 instead of threshold=2."
    )


@test("COOLBET-CDP-CLASSIFY-TIGHT — diagnose only returns jwt_expired when token lives in a KNOWN auth key")
def test_coolbet_cdp_classify_tight():
    """COOLBET-CDP-CLASSIFY-TIGHT (B2, 2026-06-16): tightens
    diagnose_cdp_jwt_state so `jwt_expired` only fires when a JWT-shaped
    value lives in a known auth key (cbauth + legacy fallbacks). Before
    this, ANY JWT-shape value anywhere in localStorage (analytics tokens,
    third-party scripts) tripped jwt_expired — which routed B4 self-heal
    toward a Page.reload that can't actually recover anything.

    With the fix, the previously-observed `jwt_expired` against today's
    state correctly resolves to `logged_out` (cbauth missing, all the
    other JWT-shape values aren't auth slots)."""
    import pathlib
    bs = pathlib.Path("workers/automation/coolbet_browser_sync.py").read_text()
    diag_block = bs[bs.index("def diagnose_cdp_jwt_state("):
                    bs.index("def auto_launch_cdp_chrome(")]
    # Two passes: first known auth keys, then defensive full-scan.
    assert "Pass 1" in diag_block and "Pass 2" in diag_block, (
        "diagnose must use the two-pass classification — Pass 1 over "
        "known auth keys (cbauth + fallbacks) for jwt_expired/valid, "
        "Pass 2 over all values for `valid` only (logged_out otherwise)."
    )
    # The defensive Pass 2 must NOT produce jwt_expired — only valid.
    # Falling through to logged_out is the correct behaviour when the
    # only JWT-shape values are non-auth.
    pass2_idx = diag_block.index("Pass 2")
    pass2_block = diag_block[pass2_idx:diag_block.index("# Logged-out:")]
    assert '"jwt_expired"' not in pass2_block, (
        "Pass 2 must not produce jwt_expired — that state is reserved for "
        "JWT-shape values found in known auth keys (Pass 1)."
    )


@test("WEEKLY-BOT-REVIEW-CS2-FILTER + CALIBRATION-ECE-BY-BIN — CS2 bots excluded; ECE bin section present")
def test_weekly_bot_review_cs2_filter_and_ece():
    """WEEKLY-BOT-REVIEW-CS2-FILTER (2026-06-21): excludes bot_cs2_* from
    the soccer-only weekly bot review. CS2 bets land in cs2_real_bets
    table (not simulated_bets / real_bets), so CS2 bots showed 0/0/0
    in this report and just polluted the dormant footer.

    CALIBRATION-ECE-BY-BIN (2026-06-21): adds a per-10pp-bin predicted
    vs actual win-rate table to the weekly digest. Surfaces miscalibration
    regressions within 7 days. Origin: tonight's GLOBAL-PLATT-OVERCONFIDENCE
    audit took 26 days from v20260607 promotion to discover the $5,800/yr
    leak. With this section in place, similar regressions surface on the
    next Sunday digest after a Platt re-fit.

    Pin: SQL filter excludes 'bot_cs2_%' in _fetch_active_bots;
    _print_calibration_section exists; bins on calibrated_prob in 10pp
    steps; flags significant gaps (|gap| > max(5pp, 1.96σ))."""
    import pathlib

    review = pathlib.Path("scripts/weekly_bot_review.py").read_text()

    # CS2 filter must be in the query, not a Python-side post-filter
    # (post-filter would still hit the DB and would be inconsistent with
    # the "where is_active" pattern).
    fetch_block = review[review.index("def _fetch_active_bots("):
                          review.index("def _fetch_sim_bets(")]
    assert "bot_cs2_%" in fetch_block, (
        "_fetch_active_bots must exclude bot_cs2_* (CS2 bets land in "
        "cs2_real_bets, not soccer simulated_bets / real_bets — they show "
        "0/0/0 here and pollute the dormant footer)."
    )

    # Calibration section function must exist.
    assert "def _print_calibration_section(" in review, (
        "weekly_bot_review.py must define _print_calibration_section() — "
        "the per-10pp-bin ECE audit that surfaces calibration regressions."
    )

    cal_block = review[review.index("def _print_calibration_section("):
                        review.index("def _print_bot_block(")]

    # Must read calibrated_prob from simulated_bets (not model_probability)
    # because the production-relevant calibration is the post-shrinkage
    # one the placer actually uses.
    assert "calibrated_prob" in cal_block, (
        "_print_calibration_section must read calibrated_prob (post-shrinkage, "
        "the actual production calibration) — model_probability is pre-stage-1 "
        "and wouldn't surface the regressions we care about."
    )

    # Significance test must be present so single-bet variance doesn't
    # spam the operator with false alarms.
    assert "1.96" in cal_block, (
        "_print_calibration_section must apply a 1.96σ significance test — "
        "without it, a 60-70% bin with n=10 and a 7pp gap would flag, "
        "even though the binomial standard error there is ~15pp."
    )
    assert "5pp" in cal_block or "0.05" in cal_block, (
        "_print_calibration_section must also require |gap| > 5pp absolute — "
        "1.96σ alone fires on small but statistically real gaps that aren't "
        "materially significant for ROI."
    )

    # Section must be called from main() between HEADLINE and ACTIONABLE
    # blocks so the operator sees the calibration warning BEFORE drilling
    # into bot-by-bot blocks.
    main_block = review[review.index("def main():"):]
    headline_idx = main_block.index("=== HEADLINE ===")
    cal_call_idx = main_block.index("_print_calibration_section(")
    actionable_idx = main_block.index("ACTIONABLE")
    assert headline_idx < cal_call_idx < actionable_idx, (
        "_print_calibration_section must be called AFTER the HEADLINE line "
        "and BEFORE the ACTIONABLE section so the operator reads it in "
        "context, not buried below 30 bot blocks."
    )


@test("ISOTONIC-ACTIVATE-V20260621 — isotonic .pkl present for 1x2_home/away/over_25, absent for draw/btts_yes")
def test_isotonic_activate_v20260621():
    """ISOTONIC-ACTIVATE-V20260621 (2026-06-21): closes GLOBAL-PLATT-OVERCONFIDENCE
    by activating the dormant isotonic infrastructure for the v20260621
    bundle. Fitted via fit_isotonic_offline.py + uploaded to Storage so
    Railway hydrates on cache miss.

    Selective activation — fitted 5 markets, kept the 3 that help
    fired-bets ECE, discarded the 2 that hurt:

      KEPT (helps on fired-bets subset):
        isotonic_1x2_home.pkl   n=856  ECE 0.087 → 0.054 (−0.033)
        isotonic_1x2_away.pkl   n=100  ECE 0.106 → 0.085 (−0.020)
        isotonic_over_25.pkl    n=217  (held-out MFV ECE 0.124 → 0.051)

      DISCARDED (hurts on fired-bets subset):
        isotonic_1x2_draw.pkl   n=95   ECE 0.148 → 0.196 (+0.048; thin sample)
        isotonic_btts_yes.pkl   n=8    btts_yes already has good Platt
                                       (today's fit: ECE 14.9% → 1.4% on n=165)

    apply_isotonic() in improvements.py:377 falls back to apply_platt
    on missing market — so a deleted .pkl is a graceful no-op for that
    selection, preserving the current production behaviour there.

    Activation: operator flips STAGE2_CALIBRATOR=isotonic on Railway
    after reading the validation table. Smoke pins file presence in
    the bundle dir + .pkl loadability + apply_isotonic graceful-fallback
    contract."""
    import pathlib
    import joblib

    bundle = pathlib.Path("data/models/soccer/v20260621")
    # The model bundle dir is not in git — it's hydrated on demand from
    # Supabase Storage by ensure_local_bundle. In CI (and any fresh
    # checkout), the dir won't exist. Skip the file-presence portion of
    # the test in that case; the activation contract is enforced by
    # presence-in-Storage, which is verified by the ML-BUNDLE-STORAGE
    # smoke (already runs separately) plus the Storage-listing check
    # below. The kept-files contract is still pinned via the Storage
    # OPTIONAL_FILES list in workers/model/storage.py.
    if not bundle.exists():
        raise SkipTest("v20260621 bundle dir not local — file-presence portion "
                       "skipped. Storage-list portion still runs.")

    # Selectively activated — these MUST be present.
    for keep in ("isotonic_1x2_home.pkl", "isotonic_1x2_away.pkl", "isotonic_over_25.pkl"):
        p = bundle / keep
        assert p.exists(), (
            f"{keep} must be present — fitted 2026-06-21 because it helped "
            f"fired-bets ECE. Re-run scripts/fit_isotonic_offline.py "
            f"--version v20260621 if missing."
        )
        # Pickle must load — guard against corrupted files.
        try:
            iso = joblib.load(p)
        except Exception as e:
            raise AssertionError(f"{keep} won't unpickle: {e}")
        # IsotonicRegression must support .predict()
        assert hasattr(iso, "predict"), (
            f"{keep} doesn't expose .predict() — apply_isotonic will fail at runtime."
        )

    # Selectively discarded — these MUST be absent so apply_isotonic falls
    # back to apply_platt for those selections (current production behaviour).
    for skip in ("isotonic_1x2_draw.pkl", "isotonic_btts_yes.pkl"):
        p = bundle / skip
        assert not p.exists(), (
            f"{skip} must be ABSENT — fitting it 2026-06-21 made fired-bets "
            f"ECE worse (draw +0.048, btts_yes had no benefit over existing Platt). "
            f"If you intentionally re-fit, validate fired-bets ECE first."
        )

    # apply_isotonic's graceful-fallback contract — missing .pkl → fall back
    # to apply_platt, which is no-op for 1x2_draw (no Platt row in DB) and
    # operates on its own learned coefficients for btts_yes. Either way, no
    # crash, no silent garbage.
    imp = pathlib.Path("workers/model/improvements.py").read_text()
    assert "apply_platt(prob, market)" in imp, (
        "apply_isotonic must fall back to apply_platt on missing market — "
        "otherwise discarding an isotonic .pkl crashes the placer."
    )


@test("B-ML3-BETS-MODE-1X2-FILTER — non-1X2 bets are skipped, not home-1X2-proxied")
def test_b_ml3_bets_mode_1x2_filter():
    """B-ML3-BETS-MODE-1X2-FILTER (2026-06-21): closes the silent training-
    data pollution discovered during B-ML3-COVERAGE-EXTEND investigation.

    Audit 2026-06-21 found 22.6% of the 60d --bets-mode training set
    (121/535 rows) was polluted: OU/BTTS/AH/DC bets where the loader
    silently fell back to sel='home' and pulled 1X2-home features
    (pinnacle_line_move_home_at_t6h etc.) joined to OU/BTTS/AH/DC CLV
    labels. Features describe one market, label describes a different
    one — pure noise the model attenuates 1X2 signal trying to fit.

    Fix: skip non-1X2 rows in _load_bets_mode_data and surface the count.

    The meta-model is architecturally 1X2-only by feature schema — the
    selection-specific MFV columns (pinnacle_line_move_{sel}_at_t6h,
    sharp_consensus_{sel}_at_t6h, opening_implied_{sel}) ONLY exist for
    {home, draw, away}. Per-market meta-modelling requires its own
    bundles with market-specific features."""
    import pathlib

    tb = pathlib.Path("scripts/train_b_ml3.py").read_text()

    # The bug we're fixing: `sel = "home"` fallback for non-1X2 selections.
    # If the old behaviour comes back, this fires.
    bets_block = tb[tb.index("def _load_bets_mode_data("):]
    assert 'sel = "home"' not in bets_block, (
        "_load_bets_mode_data must NOT fall back to sel='home' for non-1X2 "
        "rows — that pollutes training with 1X2 features joined to non-1X2 "
        "CLV labels. Audit found 22.6% of training rows were this pollution."
    )
    # Replacement behaviour: count + skip.
    assert "skipped_non_1x2" in bets_block, (
        "_load_bets_mode_data must track skipped_non_1x2 — without the "
        "counter the pollution rate is invisible in retrain logs."
    )
    # The skip must come AFTER sel lookup, not change the lookup logic itself.
    assert "continue" in bets_block, (
        "_load_bets_mode_data must `continue` on non-1X2 selections, not "
        "transform them. Otherwise the home-proxy bug returns silently."
    )

    # Call-site comment must reflect the architectural reality, not the
    # old "v2.1 training" framing that misled the B-ML3-COVERAGE-EXTEND task.
    pl = pathlib.Path("workers/jobs/daily_pipeline_v2.py").read_text()
    assert "1X2-only" in pl or "1x2-only" in pl.lower(), (
        "daily_pipeline_v2.py must document that the meta-model is "
        "architecturally 1X2-only — without the documentation, future "
        "tasks will re-file the same B-ML3-COVERAGE-EXTEND premise."
    )


@test("RETRAIN-HEALTHCHECK — alerts on stale weekly_retrain or 2+ consecutive failures")
def test_retrain_healthcheck():
    """RETRAIN-HEALTHCHECK (2026-06-21): closes a silent-failure class.
    On 2026-06-07 and 2026-06-14 the Sunday weekly_retrain job exited 1
    with no Telegram and no email. Discovered only when manually checking
    pipeline_runs while diagnosing why bets still tagged v20260607 two
    weeks later. Cost: a week of v20260621's BETTER-on-8-markets gains.

    Fix mirrors COOLBET-DAEMON-HEALTHCHECK: Railway-side job runs Mon/Tue
    09:00 UTC, queries pipeline_runs for the latest weekly_retrain runs,
    classifies as stale (>9d since last success) / failing (2+ consecutive
    non-completed) / healthy, and Telegrams accordingly. DB-backed dedup
    via the new pipeline_health_state table (migration 258) so the alert
    survives Railway redeploys.

    Pin: migration 258 + job module + both stale + failing branches + the
    dedup table interaction + scheduler hook with Mon/Tue cron."""
    import pathlib

    mig = pathlib.Path("supabase/migrations/258_pipeline_health_state.sql").read_text()
    assert "pipeline_name      TEXT        PRIMARY KEY" in mig or "pipeline_name TEXT PRIMARY KEY" in mig.replace(" "*8, " "), (
        "Migration 258 must define pipeline_health_state with pipeline_name "
        "as PRIMARY KEY — UPSERT semantics depend on this."
    )
    assert "last_alert_at" in mig and "TIMESTAMPTZ" in mig, (
        "Migration must include last_alert_at TIMESTAMPTZ — the dedup column."
    )

    job_path = pathlib.Path("workers/jobs/retrain_healthcheck.py")
    assert job_path.exists(), "retrain_healthcheck job module must exist."
    job = job_path.read_text()

    assert "def run_retrain_healthcheck(" in job, (
        "job module must export run_retrain_healthcheck() — the entry point "
        "the scheduler wraps."
    )

    # Both alert conditions must be implemented in the classifier.
    eval_block = job[job.index("def _evaluate_health("):
                      job.index("def _format_alert(")]
    assert '"stale"' in eval_block, (
        "_evaluate_health must produce 'stale' when last completed run is "
        "older than the threshold (default 9 days)."
    )
    assert '"failing"' in eval_block, (
        "_evaluate_health must produce 'failing' when N consecutive "
        "non-completed runs follow the last success."
    )

    # DB-backed dedup must read AND write — without write the dedup is no-op.
    assert "_read_dedup_row(" in job and "_set_dedup_row(" in job, (
        "job must both read and write pipeline_health_state. In-process "
        "dedup is what failed for the existing Mac daemon alert — "
        "DB-backed is the entire point."
    )

    # Recovery path must clear the dedup so the NEXT outage gets fresh alerts.
    run_block = job[job.index("def run_retrain_healthcheck("):]
    assert "_set_dedup_row(ts=None" in run_block or "_set_dedup_row(ts = None" in run_block, (
        "recovery path must CLEAR last_alert_at by writing NULL — without "
        "the clear, the next outage's first alert is dedup-skipped."
    )

    # Scheduler hook + Mon/Tue cron.
    sched = pathlib.Path("workers/scheduler.py").read_text()
    assert "def job_retrain_healthcheck(" in sched, (
        "scheduler must define job_retrain_healthcheck wrapper."
    )
    assert 'id="retrain_healthcheck"' in sched, (
        "scheduler must register the job with id='retrain_healthcheck'."
    )
    hook_idx = sched.index('id="retrain_healthcheck"')
    hook_block = sched[max(0, hook_idx - 500):hook_idx + 200]
    assert 'day_of_week="mon,tue"' in hook_block, (
        "schedule must run Mon AND Tue — Sunday-03:00 failures need a "
        "first-business-day alert; Mon-only would miss a Mon-failure "
        "until next Sunday."
    )


@test("BOT-MATURITY-LABEL-INVARIANT — is_active=false implies maturity_label='retired' via trigger + one-time reconcile")
def test_bot_maturity_label_invariant():
    """BOT-MATURITY-LABEL-INVARIANT (2026-06-21, memory queue task #1):
    Reconciles 28 stale bot rows where is_active=false but maturity_label
    was still 'beta' / 'calibrated' / 'active' / 'testing' / 'experimental'
    (legacy state from before this invariant was codified). Adds a trigger
    so the invariant is maintained on every future is_active flip.

    Why this matters: every audit, weekly_bot_review, and admin surface
    that displays maturity_label has to special-case 'inactive but labelled
    something else'. At least one prior bug (2026-06-13 bot_high_alignment
    incident) traced back to maturity_label being checked without an
    accompanying is_active check. The invariant removes the entire bug
    class.

    Pin: migration 257 exists + does both the UPDATE and the trigger;
    the trigger is BEFORE-INSERT-OR-UPDATE so it intercepts writes from
    every code path (not just specific Python helpers); is_active=true
    is deliberately NOT mirrored (reactivation requires an explicit
    operator label choice — see MODEL-BTTS-REACTIVATE 2026-06-21)."""
    import pathlib

    mig = pathlib.Path("supabase/migrations/257_bots_maturity_label_invariant.sql").read_text()

    # One-time reconcile must be present — without it the existing 28 stale
    # rows stay stale even after the trigger is installed.
    assert "UPDATE bots" in mig and "maturity_label = 'retired'" in mig, (
        "Migration must perform the one-time UPDATE to set maturity_label "
        "= 'retired' for existing is_active=false rows. Without this, the "
        "fix only applies to future retirements."
    )

    # Trigger function must exist.
    assert "CREATE OR REPLACE FUNCTION bots_set_retired_label()" in mig, (
        "Migration must define bots_set_retired_label() — the trigger "
        "body that maintains the invariant."
    )

    # Trigger must fire BEFORE INSERT OR UPDATE on is_active. AFTER triggers
    # can't modify NEW.maturity_label; AFTER-INSERT can't intercept the
    # write either. Both pieces are load-bearing.
    assert "BEFORE INSERT OR UPDATE OF is_active" in mig, (
        "Trigger must be BEFORE INSERT OR UPDATE OF is_active — AFTER "
        "triggers can't modify the row being written, and a trigger that "
        "doesn't watch INSERT misses the case where a bot is created "
        "directly with is_active=false."
    )

    # Trigger function must set maturity_label = 'retired' on the false branch.
    func_block = mig[mig.index("CREATE OR REPLACE FUNCTION bots_set_retired_label"):
                     mig.index("$$ LANGUAGE plpgsql;")]
    assert "NEW.maturity_label := 'retired'" in func_block, (
        "Trigger body must assign NEW.maturity_label = 'retired' when "
        "is_active is false. Anything else breaks the invariant."
    )
    assert "NEW.is_active = FALSE" in func_block, (
        "Trigger body must gate on NEW.is_active = FALSE — without the "
        "gate, every bot row would get 'retired' label including active "
        "bots being updated for other reasons."
    )

    # Reactivation invariant: the trigger must NOT auto-reset maturity_label
    # on is_active flipping back to true (that's an explicit operator choice,
    # see MODEL-BTTS-REACTIVATE picking 'beta' deliberately).
    assert "NEW.is_active = TRUE" not in func_block, (
        "Trigger must NOT mirror the invariant in the is_active=true "
        "direction — reactivation requires an explicit maturity choice "
        "by the operator (e.g. 'beta' for a 4-week observation window)."
    )

    # weekly_bot_review.py must surface the dormant bucket so the operator
    # can spot zero-activity bots that would otherwise be hidden by the
    # filter-or-include choice.
    review = pathlib.Path("scripts/weekly_bot_review.py").read_text()
    assert "dormant" in review.lower(), (
        "weekly_bot_review.py must include a DORMANT footer for bots with "
        "zero sim and zero real activity in 90d — collapsing them keeps "
        "the digest readable, surfacing them keeps the operator aware "
        "(e.g. calibrated bot_dnb_specialist firing zero is a signal, "
        "not noise)."
    )


@test("COOLBET-DAEMON-HEALTHCHECK — Railway-side health alert for silent / sustained-erroring daemon")
def test_coolbet_daemon_healthcheck():
    """COOLBET-DAEMON-HEALTHCHECK (2026-06-21): closes the alerting gap
    that left a 3-day outage silent on 2026-06-18 → 21. Three reasons the
    in-process Mac daemon alert path can fail:

      1. alert_fired_this_burst flag — only one alert per process
         lifetime per failure burst; no clean ticks = no further alerts.
      2. In-process Telegram dedup — dies with the process.
      3. Mac daemon IS the alerter — Mac sleep / daemon crash kills the
         alerter and the placer at the same time.

    Fix: new Railway job (every 30 min) reads coolbet_session_state +
    coolbet_heal_log and Telegrams when the daemon is silent OR
    sustainedly erroring. DB-backed dedup via last_health_alert_at
    (migration 256) survives Railway redeploys.

    Pin: migration 256 column, job module, alert/recovery code paths,
    scheduler hook with 30-min cron."""
    import pathlib

    mig = pathlib.Path("supabase/migrations/256_coolbet_daemon_healthcheck.sql").read_text()
    assert "last_health_alert_at" in mig and "TIMESTAMPTZ" in mig, (
        "Migration 256 must add last_health_alert_at TIMESTAMPTZ — the "
        "DB-backed dedup that survives Railway redeploys."
    )

    job_path = pathlib.Path("workers/jobs/coolbet_daemon_healthcheck.py")
    assert job_path.exists(), (
        "workers/jobs/coolbet_daemon_healthcheck.py must exist — this is "
        "the Railway-side alerter."
    )
    job = job_path.read_text()
    assert "def run_daemon_healthcheck(" in job, (
        "job module must export run_daemon_healthcheck() — the scheduler "
        "calls this every 30 min."
    )

    # Both alert conditions must be present — without one of them the
    # job can't catch the corresponding failure class.
    eval_block = job[job.index("def _evaluate_health("):
                      job.index("def _format_alert(")]
    assert '"silent"' in eval_block, (
        "_evaluate_health must produce 'silent' status when "
        "mac_daemon_last_tick_at is missing or stale."
    )
    assert '"erroring"' in eval_block, (
        "_evaluate_health must produce 'erroring' status when last tick "
        "has errors > 0 AND no recent successful auto-heal."
    )

    # Sustained-error check requires consulting coolbet_heal_log — without
    # this, every transient errored tick fires an alert and the operator
    # gets spammed during normal self-heal cycles.
    assert "_last_successful_heal_at(" in job, (
        "job must check coolbet_heal_log for recent successful heals to "
        "distinguish sustained outages from transient blips."
    )

    # Dedup must be DB-backed (not in-process) — otherwise we reintroduce
    # the Mac daemon's failure mode this job is supposed to fix.
    assert "_set_last_health_alert_at(" in job, (
        "job must write last_health_alert_at on alert send — DB-backed "
        "dedup is the entire point (in-process dedup is what failed)."
    )

    # COOLBET-HEALTHCHECK-JWT-AWARE (2026-06-22): the original
    # _evaluate_health only branched on `silent` or `erroring`. That
    # missed the case where the daemon ticks SILENT-WHEN-EMPTY
    # (errors=0, no work) while the JWT silently expires — a real
    # 2026-06-22 morning state. Add a jwt_stale branch gated on
    # pending calibrated picks within KO window.
    assert '"jwt_stale"' in eval_block, (
        "_evaluate_health must produce 'jwt_stale' when JWT is expired "
        "AND calibrated picks have kickoff within the watch window. "
        "Without it, a clean-tick + expired-JWT state stays invisible "
        "until the first placement attempt fails."
    )
    assert "_pending_calibrated_picks_in_ko_window(" in job, (
        "job must check pending calibrated picks to gate the jwt_stale "
        "alert. Without the gate, every idle Sunday→Monday morning "
        "would alert even though nothing's broken."
    )
    # Recovery message path — after an alert was sent and the daemon comes
    # back online, the operator needs to know the incident closed.
    run_block = job[job.index("def run_daemon_healthcheck("):]
    assert "recovery_sent" in run_block, (
        "run_daemon_healthcheck must surface a recovery_sent counter — "
        "without the recovery Telegram, the operator is left wondering "
        "if the daemon is still down."
    )
    # alert routing must include jwt_stale otherwise the evaluation
    # produces the new status but no Telegram is ever sent for it.
    assert '"jwt_stale"' in run_block, (
        "run_daemon_healthcheck must route status='jwt_stale' to the "
        "alert path. Adding the classifier without wiring it to the "
        "sender is silent-fail by omission."
    )
    assert "_set_last_health_alert_at(None)" in run_block, (
        "recovery path must CLEAR last_health_alert_at — otherwise the "
        "next outage's first alert gets dedup-skipped."
    )

    # Scheduler hook — without this the job never actually runs.
    sched = pathlib.Path("workers/scheduler.py").read_text()
    assert "def job_coolbet_daemon_healthcheck(" in sched, (
        "scheduler must define job_coolbet_daemon_healthcheck wrapper."
    )
    assert "coolbet_daemon_healthcheck" in sched and 'id="coolbet_daemon_healthcheck"' in sched, (
        "scheduler must register the job with a stable id."
    )
    # Cadence: must run sub-hourly so a 90-min-silent threshold actually
    # triggers in the same hour the daemon dies.
    hook_idx = sched.index('id="coolbet_daemon_healthcheck"')
    hook_block = sched[max(0, hook_idx - 500):hook_idx + 200]
    assert ("CronTrigger(minute=" in hook_block), (
        "scheduler hook must use a sub-hourly CronTrigger so a daemon "
        "death is detected within one cycle."
    )


@test("CDP-NEW-METHOD-PUT — /json/new uses PUT (Chrome 124+ rejects GET with 405)")
def _():
    """CDP-NEW-METHOD-PUT (2026-06-24): closes the auto-heal regression
    surfaced by 3 overnight cdp_auto_login failures (2026-06-21 → 24).
    Chrome 124+ rejects `GET /json/new?<url>` with HTTP 405 Method Not
    Allowed — a CSRF mitigation because the GET form let any web page
    open arbitrary tabs in CDP-Chrome. PUT works on both new and old
    Chrome. Without this fix, every overnight logged_out → auto-heal
    fails to open a fresh Coolbet tab, leaving the daemon stuck.

    Pin: _http_put_json helper exists; the /json/new call site uses
    _http_put_json not _http_get_json."""
    bs = _engine_path("workers/automation/coolbet_browser_sync.py").read_text()

    assert "async def _http_put_json(" in bs, (
        "_http_put_json helper must exist — it's the PUT variant of "
        "_http_get_json that Chrome 124+ requires on /json/new."
    )
    put_block = bs[bs.index("async def _http_put_json("):]
    put_block = put_block[:put_block.index("\n\n")]
    assert 'method="PUT"' in put_block, (
        "_http_put_json must pass method='PUT' to urllib.request.Request — "
        "default GET is what Chrome 124+ rejects."
    )

    # /json/new call site must use the PUT helper.
    json_new_idx = bs.index("/json/new?https://www.coolbet.com/")
    surrounding = bs[max(0, json_new_idx - 300):json_new_idx + 100]
    assert "_http_put_json" in surrounding, (
        "The /json/new call site must use _http_put_json, not "
        "_http_get_json. Chrome 124+ rejects GET on this endpoint."
    )


@test("COOLBET-SELFHEAL-PROFILE-PICKER — chrome_at_profile_picker state short-circuits auto_self_heal")
def test_coolbet_selfheal_profile_picker():
    """COOLBET-SELFHEAL-PROFILE-PICKER (2026-06-21): closes a recovery gap
    discovered live this date — Chrome restarted into chrome://profile-picker/
    on 2026-06-19, and the existing auto_self_heal stalled at no_coolbet_tab
    for 9 consecutive attempts over 44h. /json/new silently fails when no
    profile is loaded (CDP can't drive chrome:// UI), so `open_coolbet_tab`
    returns ok=False every time and the daemon spins. No bets placed for 3 days.

    Fix: diagnose_cdp_jwt_state probes /json/list when no Coolbet tab is
    found, classifying the picker case as `chrome_at_profile_picker`.
    auto_self_heal returns immediately with an actionable operator message
    (don't waste the next 4.5h retrying the same `open_coolbet_tab` loop).
    Daemon's _notify_consecutive_failures hint dict gets a matching entry
    so the Telegram alert tells the operator exactly what to click.

    Pin: helper, new state in diagnose, early-return in auto_self_heal,
    daemon recovery hint."""
    import pathlib

    bs = pathlib.Path("workers/automation/coolbet_browser_sync.py").read_text()

    assert "def _chrome_at_profile_picker(" in bs, (
        "browser_sync must export _chrome_at_profile_picker helper — it does "
        "the /json/list probe to detect 'all tabs are chrome://profile-picker/'."
    )

    # Diagnose must branch to the new state in the no-coolbet-tab path —
    # without this, the daemon never learns it's stuck at the picker.
    diag_block = bs[bs.index("def diagnose_cdp_jwt_state("):
                    bs.index("def auto_launch_cdp_chrome(")]
    assert '"chrome_at_profile_picker"' in diag_block, (
        "diagnose_cdp_jwt_state must classify the profile-picker case as "
        "chrome_at_profile_picker so the daemon can short-circuit instead of "
        "looping on no_coolbet_tab."
    )
    assert "_chrome_at_profile_picker(" in diag_block, (
        "diagnose_cdp_jwt_state must call _chrome_at_profile_picker() in the "
        "no-coolbet-tab branch — otherwise the new state never fires."
    )

    # auto_self_heal must bail out (recovered=False) on the new state — there
    # is no autonomous recovery path; only the operator can click the profile.
    heal_block = bs[bs.index("def auto_self_heal("):
                    bs.index("def _jwt_exp_seconds(")]
    assert 'state == "chrome_at_profile_picker"' in heal_block, (
        "auto_self_heal must check for chrome_at_profile_picker and return "
        "early — calling open_coolbet_tab() in this state silently fails "
        "(verified live 2026-06-19/21, 9 consecutive stall attempts)."
    )
    # The branch must short-circuit BEFORE step 3 (no_coolbet_tab open attempt),
    # so the bailout text must appear earlier in the function than the
    # `if state == "no_coolbet_tab":` step.
    picker_idx = heal_block.index('state == "chrome_at_profile_picker"')
    no_tab_idx = heal_block.index('if state == "no_coolbet_tab":')
    assert picker_idx < no_tab_idx, (
        "chrome_at_profile_picker branch must run BEFORE the no_coolbet_tab "
        "step — otherwise the daemon would still try open_coolbet_tab first "
        "and re-enter the stall loop."
    )

    # Daemon Telegram alert must include a recovery hint for the new state.
    daemon = pathlib.Path("workers/automation/coolbet_mac_daemon.py").read_text()
    assert '"chrome_at_profile_picker"' in daemon, (
        "coolbet_mac_daemon._notify_consecutive_failures must include a "
        "recovery hint for chrome_at_profile_picker — without it the alert "
        "falls back to the generic 'tail the log' message and the operator "
        "has no idea what to click."
    )


@test("COOLBET-AUTO-LOGIN-ON-HEAL — auto_self_heal recovers logged_out via cdp_auto_login when env-enabled")
def test_coolbet_auto_login_on_heal():
    """COOLBET-AUTO-LOGIN-ON-HEAL (2026-06-18): closes the last manual-touch
    failure class — Coolbet expiring the CDP session overnight, daemon
    detecting logged_out, alert firing but no auto-recovery. With this,
    auto_self_heal runs cdp_auto_login() (browser form submit, NOT the
    API endpoint that caused the 2026-06-11 SMS storm) to re-establish
    the session.

    Safety contract:
      • Gated by COOLBET_AUTO_LOGIN_ON_HEAL env var (default off — operator
        must explicitly enable in launchd plist).
      • Rate-limited to once per hour via coolbet_session_state.
        last_auto_login_attempt_at — bounds SMS exposure if Coolbet ever
        rotates device trust.
      • Records outcome (success / sms_timeout / error / rate_limited) so
        admin pages can show "auto-login working" longitudinally.
      • SMS timeout (rc=6) returns stalled with a clear action trail
        directing operator to check the browser.

    Pin: migration 255 + helpers + env gate + rate limit + cdp_auto_login
    call site + plist enablement."""
    import pathlib

    mig = pathlib.Path("supabase/migrations/255_coolbet_auto_login_rate_limit.sql").read_text()
    assert "last_auto_login_attempt_at" in mig and "TIMESTAMPTZ" in mig, (
        "Migration 255 must add last_auto_login_attempt_at TIMESTAMPTZ."
    )
    assert "last_auto_login_outcome" in mig, (
        "Migration 255 must add last_auto_login_outcome TEXT."
    )

    state = pathlib.Path("workers/automation/coolbet_state.py").read_text()
    assert "def auto_login_recently_attempted(" in state, (
        "coolbet_state must define auto_login_recently_attempted() — "
        "the rate-limit gate (default 60min)."
    )
    assert "def record_auto_login_attempt(" in state, (
        "coolbet_state must define record_auto_login_attempt() — writes "
        "outcome to last_auto_login_outcome."
    )

    bs = pathlib.Path("workers/automation/coolbet_browser_sync.py").read_text()
    heal_block = bs[bs.index("def auto_self_heal("):
                    bs.index("def _jwt_exp_seconds(")]
    # Env gate is load-bearing — without it, every Coolbet session expiry
    # would auto-fire a browser login. We want explicit opt-in.
    assert 'COOLBET_AUTO_LOGIN_ON_HEAL' in heal_block, (
        "auto_self_heal must check COOLBET_AUTO_LOGIN_ON_HEAL env var — "
        "default-off so unattended deployments don't auto-login."
    )
    # Rate-limit gate must be checked before invoking the form submit.
    assert "auto_login_recently_attempted(" in heal_block, (
        "auto_self_heal must call auto_login_recently_attempted() before "
        "cdp_auto_login — protects against SMS spam if Coolbet rotates "
        "device trust."
    )
    assert "cdp_auto_login(" in heal_block, (
        "auto_self_heal must invoke cdp_auto_login() in the logged_out "
        "branch when the env gate is open."
    )
    # SMS timeout MUST be handled distinctly (rc=6 → stalled with hint).
    # If we treated SMS-timeout like other errors, the operator wouldn't
    # know to check the browser.
    assert "rc == 6" in heal_block, (
        "auto_self_heal must handle cdp_auto_login rc=6 (SMS timeout) "
        "with a distinct stalled+hint return, not generic error."
    )
    # All outcomes recorded so longitudinal observability works.
    for outcome in ('"success"', '"sms_timeout"', '"error"', '"rate_limited"'):
        assert outcome in heal_block, (
            f"auto_self_heal must record outcome={outcome} via "
            "record_auto_login_attempt — admin pages depend on this set."
        )

    # Plist enablement — the operator's deliberate opt-in lives here, not
    # in code defaults. Pinned so a future plist refresh can't lose it.
    plist = pathlib.Path("local/launchd/com.oddsintel.coolbet-mac-daemon.plist").read_text()
    assert "COOLBET_AUTO_LOGIN_ON_HEAL" in plist and "<string>true</string>" in plist, (
        "Mac daemon plist must set COOLBET_AUTO_LOGIN_ON_HEAL=true — the "
        "operator's explicit opt-in to browser-form auto-login on logged_out."
    )


@test("COOLBET-HEAL-AUDIT-LOG — every auto_self_heal invocation writes a row to coolbet_heal_log")
def test_coolbet_heal_audit_log():
    """COOLBET-HEAL-AUDIT-LOG (2026-06-17): migration 253 + log_heal_attempt
    helper + auto_self_heal's _finish() wrapper. Every heal attempt
    (auto, operator_cli, operator_tg, pipeline) lands in coolbet_heal_log
    with state-before/after, recovered flag, actions, message, duration.

    Pin: migration creates the table with all expected columns; helper
    exists in coolbet_state; auto_self_heal uses _finish() at every
    return path; triggered_by parameter is plumbed through the CLI."""
    import pathlib

    mig = pathlib.Path("supabase/migrations/253_coolbet_heal_log.sql").read_text()
    for col in ("triggered_at", "triggered_by", "state_before", "state_after",
                 "recovered", "actions", "message", "duration_s"):
        assert col in mig, f"Migration 253 must add column '{col}'."

    state = pathlib.Path("workers/automation/coolbet_state.py").read_text()
    assert "def log_heal_attempt(" in state, (
        "coolbet_state must define log_heal_attempt() — the writer."
    )

    bs = pathlib.Path("workers/automation/coolbet_browser_sync.py").read_text()
    heal_block = bs[bs.index("def auto_self_heal("):
                    bs.index("def _jwt_exp_seconds(")]
    assert "triggered_by:" in heal_block, (
        "auto_self_heal must accept triggered_by parameter."
    )
    assert "def _finish(" in heal_block, (
        "auto_self_heal must define inner _finish() helper for centralised "
        "audit-log writes on every return path."
    )
    # All return points must go through _finish, not bare return {...}.
    # Cheap heuristic: count "return {" (bare dict) vs "return _finish".
    bare_returns = heal_block.count("return {")
    finish_returns = heal_block.count("return _finish(")
    # _probe inner helper has 1 bare return — allow that.
    assert bare_returns <= 1, (
        f"auto_self_heal has {bare_returns} bare `return {{` outside _probe "
        f"— all heal-result returns must go through _finish() so the audit "
        f"log fires."
    )
    assert finish_returns >= 4, (
        f"Expected ≥4 _finish() returns (one per state branch), found "
        f"{finish_returns}."
    )


@test("COOLBET-INLINE-HEAL-BUTTONS — Telegram alerts carry 🔄/⏸/▶ buttons; daemon drains operator commands")
def test_coolbet_inline_heal_buttons():
    """COOLBET-INLINE-HEAL-BUTTONS (2026-06-17): closes the operator-touch
    gap exposed during yesterday's recovery. Daemon-fail-burst alerts and
    the daily summary now carry inline buttons; webhook routes the taps
    to coolbet_daemon_commands (heal) or direct DB updates (pause/resume);
    daemon polls the commands table every ~30s in its sleep loop.

    Pin: migration 254 + helpers + button markup + daemon poll + webhook
    handler."""
