    assert "if edge_pct < 3.0:" in l_block, "Strategy L edge gate must be < 3.0 (INPLAY-LOOSEN-SILENT-L)"
    assert "if edge_pct < 4.0:" not in l_block, "Strategy L stale < 4.0 gate found — must be removed"


