@test("INPLAY-METADATA-STALENESS — inplay picks write match minute + score to first-class columns")
def _():
    """Inplay picks should populate `match_minute_at_pick`,
    `score_home_at_pick`, `score_away_at_pick` so the UI can show
    'In-play · 23' · 0-1' without parsing the reasoning JSON.

    Guards three places:
      1. Migration 173 adds the three columns.
      2. inplay_bot._build_inplay_bet_data includes them in the payload.
      3. store_bet's optional_fields whitelist accepts them.
    """
    # 1. Migration
    mig = _engine_path("supabase/migrations/173_inplay_pick_minute_score.sql")
    assert mig.exists(), "migration 173 must exist"
    mig_src = mig.read_text()
    for col in ("match_minute_at_pick", "score_home_at_pick", "score_away_at_pick"):
        assert col in mig_src, f"migration 173 must add column {col}"

    # 2. Builder includes the fields
    builder_src = _engine_path("workers/jobs/inplay_bot.py").read_text()
    builder_block_start = builder_src.index("def _build_inplay_bet_data")
    builder_block_end = builder_src.index("\ndef ", builder_block_start + 10)
    builder_block = builder_src[builder_block_start:builder_block_end]
    assert "\"match_minute_at_pick\": cand.get(\"minute\")" in builder_block, (
        "_build_inplay_bet_data must include match_minute_at_pick from cand['minute']"
    )
    assert "\"score_home_at_pick\": cand.get(\"score_home\")" in builder_block, (
        "_build_inplay_bet_data must include score_home_at_pick from cand['score_home']"
    )
    assert "\"score_away_at_pick\": cand.get(\"score_away\")" in builder_block, (
        "_build_inplay_bet_data must include score_away_at_pick from cand['score_away']"
    )

    # 3. store_bet whitelists the fields. The file has two `optional_fields`
    # lists; we need the one inside store_bet, not the earlier helper.
    sb_src = _engine_path("workers/api_clients/supabase_client.py").read_text()
    sb_fn_start = sb_src.index("def store_bet(")
    sb_optional_start = sb_src.index("optional_fields = [", sb_fn_start)
    sb_optional_end = sb_src.index("]", sb_optional_start)
    sb_optional_block = sb_src[sb_optional_start:sb_optional_end]
    for field in ("match_minute_at_pick", "score_home_at_pick", "score_away_at_pick"):
        assert f"\"{field}\"" in sb_optional_block, (
            f"store_bet's optional_fields must include {field} so it's persisted"
        )


@test("NULL-BOOKMAKER-AH-FIX — Asian Handicap rows populate recommended_bookmaker")
def _():
    """100% of AH simulated_bets in the prior 60d had NULL
    recommended_bookmaker because daily_pipeline_v2._load_today_from_db
    only wrote AH best-odds to `ah_best` and never to `best_bookmaker`.
    The storage call looks up `best_bookmaker[mid][f"asian_handicap_{Sel} {hl:+.4g}"]`,
    so the field landed as None for every AH pick.

    Fix: write to `best_bookmaker` alongside `ah_best`, keyed in the
    storage-call format so the lookup at L3297 resolves."""
    src = _engine_path("workers/jobs/daily_pipeline_v2.py").read_text()
    # The AH branch must populate `best_bookmaker` with the storage key.
    ah_block_start = src.index("if market == \"asian_handicap\":")
    ah_block_end = src.index("continue", ah_block_start)
    ah_block = src[ah_block_start:ah_block_end]
    assert "best_bookmaker[mid][" in ah_block, (
        "AH branch must populate best_bookmaker[mid][...] so AH picks "
        "get a non-NULL recommended_bookmaker"
    )
    # Key format must mirror storage call (asian_handicap_<Sel> <hl:+.4g>).
    assert "f\"asian_handicap_{_sel_cap} {float(hl):+.4g}\"" in ah_block, (
        "AH bookmaker storage key must mirror the storage-call format "
        "f\"asian_handicap_{Sel} {hl:+.4g}\" so the lookup resolves"
    )


@test("SEO-SITEMAP-MATCHES — sitemap.ts includes match detail URLs from getMatchIdsForSitemap")
def _():
    """Pre-fix: sitemap only listed static + predictions + glossary pages, so
    Google had no way to discover /matches/[id] URLs — the highest-volume
    indexable surface. Symptom: low coverage in Search Console.

    Fix: sitemap.ts calls getMatchIdsForSitemap() (a 44-day window helper in
    engine-data.ts) and emits one entry per fixture with the row's real
    updated_at as lastModified. Sitemap revalidates hourly."""
    sitemap = _web_path("src/app/sitemap.ts")
    if not sitemap.exists():
        print("  [skip] odds-intel-web not present in CI")
        return
    src = sitemap.read_text()
    assert "getMatchIdsForSitemap" in src, "sitemap.ts must import getMatchIdsForSitemap"
    assert "matchPages" in src or "/matches/${" in src, \
        "sitemap.ts must emit per-match URLs"
    assert "export const revalidate" in src, \
        "sitemap.ts must export `revalidate` so new fixtures appear without a redeploy"

    helper = _web_path("src/lib/engine-data.ts").read_text()
    assert "export async function getMatchIdsForSitemap" in helper, \
        "engine-data.ts must export getMatchIdsForSitemap()"
    # Helper must filter to active leagues — otherwise sitemap fills with
    # fixtures from leagues we don't actually surface in the UI.
    helper_fn_start = helper.index("export async function getMatchIdsForSitemap")
    helper_fn_block = helper[helper_fn_start:helper_fn_start + 1200]
    assert "is_active" in helper_fn_block, \
        "getMatchIdsForSitemap must filter to is_active leagues"


@test("SEO-MATCH-DETAIL-JSONLD — /matches/[id] emits SportsEvent + BreadcrumbList structured data")
def _():
    """Pre-fix: only Organization JSON-LD existed (in root layout). Match detail
    pages — the highest-traffic SEO surface — had no per-page structured data,
    so they were ineligible for SportsEvent rich results in Google.

    Fix: inject SportsEvent (homeTeam/awayTeam/startDate/location) and
    BreadcrumbList (Home → Matches → fixture) into the page's JSX."""
    page = _web_path("src/app/(app)/matches/[id]/page.tsx")
    if not page.exists():
        print("  [skip] odds-intel-web not present in CI")
        return
    src = page.read_text()
    assert "\"@type\": \"SportsEvent\"" in src, \
        "match detail must emit SportsEvent JSON-LD"
    assert "\"@type\": \"BreadcrumbList\"" in src, \
        "match detail must emit BreadcrumbList JSON-LD"
    # Both schemas must use the live publicMatch data, not hardcoded values.
    assert "publicMatch.homeTeam" in src and "publicMatch.awayTeam" in src, \
        "SportsEvent must be populated from publicMatch (team names)"
    assert "application/ld+json" in src, "must render via <script type=application/ld+json>"
    # Optional SportsEvent fields Google's Rich Results Test flagged on 2026-06-03.
    # Each adds eligibility for richer rich-result surfaces.
    assert "endDate:" in src, \
        "SportsEvent must include endDate (kickoff + ~115min) — flagged by Rich Results Test"
    assert "image:" in src, \
        "SportsEvent must include image (team logos / OG fallback) — flagged by Rich Results Test"
    assert "performer:" in src, \
        "SportsEvent must include performer alongside competitor — flagged by Rich Results Test"
    # offers here represents free access to OddsIntel's predictions for this
    # match (NOT a ticket to the event); category disambiguates from ticket
    # sellers so Google doesn't pull us into ticket rich results.
    assert "offers:" in src and "\"Offer\"" in src, \
        "SportsEvent must include an Offer (free predictions access for this match)"
    assert "category:" in src and "predictions" in src.lower(), \
        "Offer must set category so Google doesn't misclassify us as a ticket seller"
    # organizer.url is linked ONLY for featured leagues that have a known
    # predictions slug — never fabricated for unknown leagues.
    assert "PREDICTION_LEAGUES.find" in src, \
        "organizer.url must be derived from PREDICTION_LEAGUES (no fake URLs)"

    # Root Organization must carry a logo URL — Search Console flags it as
    # missing when Organization schema is in root layout without a logo.
    root_layout = _web_path("src/app/layout.tsx").read_text()
    assert "\"@type\": \"Organization\"" in root_layout, \
        "root layout must keep the Organization schema"
    assert "logo:" in root_layout and "icon-512.png" in root_layout, \
        "root Organization must include a logo URL (icon-512.png)"


@test("SMOKE-SKIPTEST — _web_path raises SkipTest when odds-intel-web is absent; runner counts skips separately from failures")
def _():
    """SMOKE-SKIPTEST (2026-06-03): smoke_tests.yml only checks out this engine
    repo, but ~18 tests grep the sibling `odds-intel-web` checkout. Before
    this contract they all hard-failed in CI with FileNotFoundError, drowning
    real regressions under expected noise. Now:
      - `_web_path()` raises `SkipTest` if `_web_root` is absent.
      - `_run_one` catches SkipTest and returns status='skip'.
      - `main()` reports skips with a third counter (`⊘`), separate from `✗`.
    Pin the contract here so a future refactor of the runner doesn't silently
    re-collapse skip into pass or fail."""
    import inspect
    # Sentinel exists and is an Exception subclass
    assert issubclass(SkipTest, Exception), "SkipTest must be an Exception subclass"

    # _web_path raises SkipTest when web is missing
    import pathlib
    original = sys.modules[__name__].__dict__.get("_web_root")
    try:
        sys.modules[__name__]._web_root = pathlib.Path("/definitely/not/here")
        try:
            _web_path("anything.tsx")
        except SkipTest:
            pass  # expected
        else:
            raise AssertionError("_web_path must raise SkipTest when _web_root absent")
    finally:
        sys.modules[__name__]._web_root = original

    # Runner has the skip branch wired through
    src = inspect.getsource(_run_one)
    assert "SkipTest" in src, "_run_one must catch SkipTest and return status='skip'"
    assert '"skip"' in src, "_run_one must distinguish skip from pass/fail"

    main_src = inspect.getsource(main)
    assert 'status == "skip"' in main_src or '"skip"' in main_src, (
        "main() must surface skip in the summary so CI output is truthful"
    )


@test("COOLBET-SELECTION-CASE — Coolbet snapshot selections lowercase, matching other bookmakers + frontend lookup")
def _():
    """COOLBET-SELECTION-CASE (2026-06-03): Coolbet's `parse_market` +
    `_normalise_our_target` previously emitted Title-case 1X2 selections
    ("Home"/"Draw"/"Away") and uppercase DC ("1X"/"X2") that got written
    into `odds_snapshots` via `store_coolbet_odds_snapshot` + the presence-
    marker path in the placer. Every OTHER bookmaker in the table writes
    lowercase ("home"/"away"/"1x"/"x2"), and the frontend's
    `_mapPaperToSnapshotKey` lowercases on lookup — so all Coolbet 1X2/DC
    snapshots were invisible. /admin/place then mis-labelled every bet as
    `⚠ no market` because the match had a Coolbet row (counted via
    `matchIdsWithCoolbetEvent`) but the per-(market, selection) lookup
    missed.

    Locked here so the next refactor can't silently re-uppercase:
      - parse_market emits "home"/"draw"/"away" + "1x"/"x2"/"12".
      - _normalise_our_target returns the same lowercase form.
      - resolve_placement_target still resolves end-to-end.
    """
    from workers.automation.coolbet_explorer import (
        _normalise_our_target, parse_market, resolve_placement_target,
    )

    # 1X2: every input case maps to lowercase output
    assert _normalise_our_target("1x2", "home") == ("1x2", "home", None)
    assert _normalise_our_target("1X2", "Home") == ("1x2", "home", None)
    assert _normalise_our_target("1x2", "Away") == ("1x2", "away", None)
    assert _normalise_our_target("1x2", "DRAW") == ("1x2", "draw", None)

    # DC: every input case maps to lowercase output
    assert _normalise_our_target("double_chance", "1x") == ("double_chance", "1x", None)
    assert _normalise_our_target("double_chance", "X2") == ("double_chance", "x2", None)

    # parse_market emits lowercase for both market types
    mkt_1x2 = {
        "id": 1, "line": 0, "name": "Match Result", "market_type_id": 81,
        "outcomes": [
            {"id": 10, "result_key": "[Home]"},
            {"id": 20, "result_key": "Draw"},
            {"id": 30, "result_key": "[Away]"},
        ],
    }
    odds_1x2 = {
        10: {"value": 2.0, "odds_id": "h"},
        20: {"value": 3.4, "odds_id": "d"},
        30: {"value": 3.6, "odds_id": "a"},
    }
    sels_1x2 = {r[1] for r in parse_market(mkt_1x2, odds_1x2)}
    assert sels_1x2 == {"home", "draw", "away"}, (
        f"1X2 parse_market must emit lowercase selections, got {sels_1x2}"
    )

    mkt_dc = {
        "id": 2, "line": 0, "name": "Double Chance", "market_type_id": 1484,
        "outcomes": [
            {"id": 11, "result_key": "[Home]/Draw"},
            {"id": 22, "result_key": "[Away]/Draw"},
            {"id": 33, "result_key": "[Home]/[Away]"},
        ],
    }
    odds_dc = {11: {"value": 1.3}, 22: {"value": 1.4}, 33: {"value": 1.2}}
    sels_dc = {r[1] for r in parse_market(mkt_dc, odds_dc)}
    assert sels_dc == {"1x", "x2", "12"}, (
        f"DC parse_market must emit lowercase selections, got {sels_dc}"
    )

    # End-to-end resolve still works with mixed-case input (paper-bet shape)
    res = resolve_placement_target([mkt_1x2], odds_1x2, "1X2", "Home")
    assert res == (1, 10, "h", 2.0), f"resolve 1X2 Home wrong after lowercase: {res}"
    res = resolve_placement_target([mkt_dc], odds_dc, "double_chance", "1x")
    assert res is not None and res[1] == 11, f"resolve DC 1x wrong: {res}"


@test("PIN-CROSS-DRIFT-HELPER — per-market thresholds + news skip + fail-open behaviour")
def _():
    """PIN-CROSS-DRIFT (2026-06-03): the helper deciding whether a non-1X2 bet
    should be vetoed because Pinnacle's 1X2 line drifted significantly
    pre-KO without our news pipeline explaining it. Backtest:
    scripts/pin_drift_veto_analysis.py.

    Per-market thresholds (locked-in from 60d analysis):
      btts/o/u           → veto at abs_drift >= 0.03
      double_chance/AH   → veto at abs_drift >= 0.01
      1x2 + everything else → no veto (drift feature lives on 1x2; cross-market
        leak doesn't apply).

    Critical invariant: helper must fail-open when drift data is NULL
    (morning bets at T-12h have NULL pinnacle_line_move_*_at_t6h), and must
    NOT veto when news_impact_score explains the move."""
    from workers.model.pin_cross_drift_veto import check_pin_cross_drift_veto, get_thresholds

    # Thresholds match the empirical cohort split.
    th = get_thresholds()
    assert th["btts"] == 0.03 and th["o/u"] == 0.03, (
        "btts + o/u thresholds must be 0.03 — that's the empirical break in 60d data"
    )
    # O/U pipeline os_market values (daily_pipeline_v2 candidate_specs tuples):
    # "over_under_25" / "over_under_15" / "over_under_35" — all must be mapped.
    assert th.get("over_under_25") == 0.03, "over_under_25 must map to 0.03 (bug fix 2026-06-07)"
    assert th.get("over_under_15") == 0.03, "over_under_15 must map to 0.03"
    assert th.get("over_under_35") == 0.03, "over_under_35 must map to 0.03"
    assert th["double_chance"] == 0.01 and th["asian_handicap"] == 0.01, (
        "DC + AH thresholds must be 0.01 — DC fails from 1% upward, AH leak is in 1-3% bucket"
    )
    assert "1x2" not in th, "1x2 must not have a veto threshold — no leak in that cohort"

    # ── Veto fires when drift exceeds threshold and no news ──
    d = check_pin_cross_drift_veto("btts", 0.05, 0.0, -0.04, None)
    assert d["should_veto"] is True, "BTTS @ 5% drift with no news should veto"
    assert d["reason"] == "pin_cross_drift_unexplained"

    d = check_pin_cross_drift_veto("double_chance", 0.02, 0.0, 0.0, None)
    assert d["should_veto"] is True, "DC @ 2% drift with no news should veto (threshold 1%)"

    # BUG-FIX 2026-06-07: pipeline sends "over_under_25" not "o/u" — must fire
    d = check_pin_cross_drift_veto("over_under_25", 0.04, 0.0, 0.0, None)
    assert d["should_veto"] is True, "over_under_25 @ 4% drift must veto (was silently skipped before fix)"

    # ── Below threshold: no veto ──
    d = check_pin_cross_drift_veto("btts", 0.02, 0.0, 0.0, None)
    assert d["should_veto"] is False, "BTTS @ 2% drift is below 3% threshold — no veto"
    assert d["reason"] == "below_threshold"

    # ── News explains the move: no veto ──
    d = check_pin_cross_drift_veto("btts", 0.05, 0.0, 0.0, 0.4)
    assert d["should_veto"] is False, "Even at 5% drift, non-trivial news_impact must suppress veto"
    assert d["reason"] == "news_explained"

    # ── 1X2 never veto'd (no entry in thresholds) ──
    d = check_pin_cross_drift_veto("1x2", 0.10, -0.05, -0.05, None)
    assert d["should_veto"] is False, "1X2 never vetoed — drift feature lives on this market"

    # ── Fail-open when no drift data (morning bets) ──
    d = check_pin_cross_drift_veto("o/u", None, None, None, None)
    assert d["should_veto"] is False, "All-NULL drift (morning) must NOT veto — fail-open"
    assert d["reason"] == "no_drift_data"

    # ── Unknown market (combo, draw_no_bet): no veto, no error ──
    d = check_pin_cross_drift_veto("combo", 0.50, 0.50, -0.50, None)
    assert d["should_veto"] is False, "Unknown markets are not vetoed"


@test("PIN-CROSS-DRIFT-PIPELINE — daily_pipeline_v2 calls helper + writes shadow flag + gates on env")
def _():
    """The veto helper must be wired into daily_pipeline_v2 so it actually
    runs on bet emission. Properties asserted:
      - Helper is imported and called for non-1X2 bets.
      - Env gate PIN_CROSS_DRIFT_VETO_ENABLED defaults to false (shadow only).
      - Shadow flag (`pin_cross_drift_shadow_flag`) is written on the bet row
        regardless of activation, so we can validate the policy against
        live results before flipping the gate.
      - Migration 175 adds the shadow flag column."""
    pipeline = _engine_path("workers/jobs/daily_pipeline_v2.py").read_text()
    assert "from workers.model.pin_cross_drift_veto import check_pin_cross_drift_veto" in pipeline, (
        "daily_pipeline_v2 must import the veto helper"
    )
    assert "PIN_CROSS_DRIFT_VETO_ENABLED" in pipeline, (
        "daily_pipeline_v2 must gate active veto behind PIN_CROSS_DRIFT_VETO_ENABLED env"
    )
    assert "drop_pin_cross_drift_shadow" in pipeline, (
        "Pipeline must emit a 'drop_pin_cross_drift_shadow' funnel bucket on shadow hits"
    )
    assert "pin_cross_drift_shadow_flag" in pipeline, (
        "Bet payload must carry the shadow flag for downstream validation"
    )

    # POST-INCIDENT GUARD (2026-06-03 11:05 UTC): the initial PIN-CROSS-DRIFT
    # commit called bare execute_query() in the veto block. execute_query is
    # only imported locally inside specific functions of daily_pipeline_v2,
    # NOT at module level — so the run_morning bot loop had no execute_query
    # symbol in scope. First production run NameError'd and killed the 11:05
    # betting_pipeline. Fix: local-import alias `_eq_pin_cross`. This assertion
    # locks the pattern so a future refactor reverting to bare execute_query()
    # fails CI before it ships.
    _veto_start = pipeline.index("_pin_cross_drift_decision = None")
    _veto_end = pipeline.index("# P4: Kelly fraction", _veto_start)
    _veto_block = pipeline[_veto_start:_veto_end]
    assert "from workers.api_clients.db import execute_query as _eq_pin_cross" in _veto_block, (
        "PIN-CROSS-DRIFT veto block must import execute_query via local alias "
        "(_eq_pin_cross). Bare execute_query() NameError'd in production on "
        "2026-06-03 — do not regress."
    )
    assert "_eq_pin_cross(" in _veto_block, (
        "PIN-CROSS-DRIFT veto block must call the local _eq_pin_cross alias, "
        "not bare execute_query() — the latter is not in scope in run_morning."
    )

    # store_bet must whitelist the new field so the column is actually written.
    sb = _engine_path("workers/api_clients/supabase_client.py").read_text()
    sb_fn_start = sb.index("def store_bet(")
