@test("INPLAY-O-QUARANTINE — no post-fix inplay_o bets snuck through score-odds inversion")
def test_inplay_o_quarantine_holds():
    """INPLAY-O-QUARANTINE (2026-06-06): 62 pre-fix inplay_o bets were voided
    after back-testing showed 70% of inplay_o's reported wins came from
    inverted snapshots (winning team had longer 1x2 odds than losing team —
    physically impossible, indicates the score column lagged a goal). The
    veto in _score_odds_consistent (commit 6cf9a6a, 2026-05-30 07:32 UTC)
    blocks new inversions; this test is the regression guard.

    Asserts:
      • no settled inplay_o bet placed after FIX_DATE has an inverted snapshot
        within ±2 min of pick_time
      • at least 62 inplay_o bets are in result='void' (the quarantine holds)
    """
    from workers.api_clients.db import execute_query
    rows = execute_query("""
      WITH bets AS (
        SELECT sb.id, sb.pick_time, sb.match_id, sb.result
        FROM simulated_bets sb
        JOIN bots b ON b.id = sb.bot_id
        WHERE b.name = 'inplay_o'
          AND sb.market = '1x2'
          AND sb.pick_time >= TIMESTAMP '2026-05-30 07:32:00+00'
          AND sb.result IN ('won', 'lost')
      )
      SELECT b.id,
             (SELECT row_to_json(s.*) FROM (
                SELECT score_home, score_away, live_1x2_home, live_1x2_away
                FROM live_match_snapshots
                WHERE match_id = b.match_id
                  AND captured_at BETWEEN b.pick_time - INTERVAL '2 minutes'
                                      AND b.pick_time + INTERVAL '2 minutes'
                ORDER BY abs(extract(epoch from (captured_at - b.pick_time)))
                LIMIT 1
              ) s) AS snap
      FROM bets b
    """)
    inverted = []
    for r in rows:
        snap = r.get("snap")
        if not snap: continue
        sh, sa = snap.get("score_home"), snap.get("score_away")
        oh, oa = snap.get("live_1x2_home"), snap.get("live_1x2_away")
        if sh is None or sa is None or oh is None or oa is None: continue
        if sh == sa: continue
        if (sh > sa) != (float(oh) < float(oa)):
            inverted.append(r["id"])
    assert not inverted, (
        f"{len(inverted)} post-fix inplay_o bets placed on inverted snapshots — "
        f"the score-odds veto must be re-armed. Bet IDs: {inverted[:5]}"
    )

    void_count = execute_query("""
      SELECT count(*) AS n FROM simulated_bets sb
      JOIN bots b ON b.id = sb.bot_id
      WHERE b.name = 'inplay_o' AND sb.result = 'void'
    """)[0]["n"]
    assert void_count >= 62, (
        f"inplay_o quarantine cohort shrank: only {void_count} void bets, "
        f"expected ≥ 62 (the 2026-06-06 quarantine batch)"
    )


@test("INPLAY-N-MODEL-VS-MARKET-GATE — _check_strategy_n skips model-overconfident picks")
def test_inplay_n_model_vs_market_gate():
    """INPLAY-N-MODEL-VS-MARKET-GATE (2026-06-06): inplay_n strategy assumes
    the prematch ensemble is well-calibrated. In low-data leagues the model
    returns 65-83% prematch win probs for teams the market priced at 19-47%.
    24 bets at -50.6% ROI confirmed the model, not the market, was wrong.
    Gate: if (model_prob - market_implied) > 0.15, skip the candidate.

    Asserts:
      • _get_prematch_data SELECT includes prematch_implied_home/away
      • _check_strategy_n reads prematch_implied_{home,away} from pm dict
      • Gate fires for known-bad cases (Mbarara 0.66/0.19, St. Anna 0.83/0.35)
      • Gate does NOT fire when model and market agree (Tacoma 0.71/0.58)
    """
    import pathlib
    bot_src = pathlib.Path("workers/jobs/inplay_bot.py").read_text()
    assert "prematch_implied_home" in bot_src, "missing prematch_implied_home in inplay_bot"
    assert "prematch_implied_away" in bot_src, "missing prematch_implied_away in inplay_bot"
    assert 'pm.get("prematch_implied_home")' in bot_src, \
        "_check_strategy_n must read prematch_implied_home from pm dict"
    assert 'pm.get("prematch_implied_away")' in bot_src, \
        "_check_strategy_n must read prematch_implied_away from pm dict"
    assert "INPLAY-N-MODEL-VS-MARKET-GATE" in bot_src, \
        "gate marker comment missing from inplay_bot.py"

    # Behavioural check — exercise _check_strategy_n directly with synthetic
    # candidates that mimic the bad-data cases.
    from workers.jobs.inplay_bot import _check_strategy_n

    def _cand(score_h=0, score_a=0, minute=70, live_h=3.50, live_a=2.00):
        return {
            "minute": minute,
            "score_home": score_h,
            "score_away": score_a,
            "live_1x2_home": live_h,
            "live_1x2_away": live_a,
        }

    # Case 1: Mbarara — model 66% home, market implied 18.9%, live odds 7.50.
    # Should be SKIPPED by the gate (0.66 - 0.189 = 0.47 > 0.15).
    pm_mbarara = {
        "prematch_home_prob": 0.6607, "prematch_away_prob": 0.0918,
        "prematch_implied_home": 0.1887, "prematch_implied_away": 0.5236,
        "prematch_xg_home": 1.2, "prematch_xg_away": 1.8,
    }
    assert _check_strategy_n(_cand(score_h=1, score_a=1, minute=73, live_h=7.50, live_a=1.30),
                              pm_mbarara, has_red_card=False) is None, \
        "Mbarara case (model 66% vs market 18.9%) must be vetoed"

    # Case 2: St. Anna — model 83% home, market implied 35.5%, live odds 13.00.
    # Should be SKIPPED (0.83 - 0.355 = 0.48 > 0.15).
    pm_stanna = {
        "prematch_home_prob": 0.8312, "prematch_away_prob": 0.0238,
        "prematch_implied_home": 0.3546, "prematch_implied_away": 0.4219,
        "prematch_xg_home": 1.5, "prematch_xg_away": 1.0,
    }
    assert _check_strategy_n(_cand(score_h=0, score_a=0, minute=66, live_h=13.00, live_a=1.11),
                              pm_stanna, has_red_card=False) is None, \
        "St. Anna case (model 83% vs market 35.5%) must be vetoed"

    # Case 3: gate falls back gracefully when implied prob is missing (0/None).
    # The strategy must not crash — it should treat missing implied as "skip
    # the gate" (don't second-guess when we have no market signal).
    pm_no_implied = {
        "prematch_home_prob": 0.70, "prematch_away_prob": 0.10,
        "prematch_implied_home": None, "prematch_implied_away": None,
        "prematch_xg_home": 1.5, "prematch_xg_away": 1.0,
    }
    # Should not raise; should not be blocked by gate (later checks may still veto)
    try:
        _check_strategy_n(_cand(score_h=0, score_a=0, minute=70, live_h=2.50, live_a=4.00),
                          pm_no_implied, has_red_card=False)
    except (TypeError, ValueError) as e:
        assert False, f"gate crashed on missing implied prob: {e}"


@test("CLV-BACKFILL — scripts/clv_report.py + ingest script structure")
def test_clv_backfill_scripts():
    """CLV-BACKFILL (2026-06-06): one-off Pinnacle closing-line backfill via
    OddsPapi /historical-odds enables per-bot CLV analysis for the
    CHERRY-PICK-PLACER 2026-06-08 gate flip. Pins:

    - scripts/clv_report.py exists with the inplay-exclusion guard
      (inplay bets get bogus CLV vs pre-match close — must be filtered)
    - scripts/ingest_oddspapi_pinnacle_closes.py exists with dry-run default
      (any --execute path that writes to odds_snapshots must require explicit flag)
    - The OddsPapi marketId→1x2 decoder maps the known stable IDs:
      101=home, 102=draw, 103=away
    - The OU/AH market-id tables cover the half-lines we actually bet on
    """
    import pathlib
    clv_src = pathlib.Path("scripts/clv_report.py").read_text()
    ing_src = pathlib.Path("scripts/ingest_oddspapi_pinnacle_closes.py").read_text()

    # Inplay exclusion is the critical guard — without it CLV is meaningless
    # (live-odds bets vs pre-match close gives spurious +100%+ CLV).
    assert 'startswith("inplay_")' in clv_src, (
        "clv_report.py must exclude inplay_* bots from CLV computation — "
        "pre-match Pinnacle close is the wrong comparator for in-game bets"
    )
    assert "excluded" in clv_src and "inplay" in clv_src, (
        "the exclusion must be logged so the analyst sees the count"
    )

    # 1x2 outcome decoder must use the stable IDs we observed in OP responses
    # (either as oid→sel or sel→oid mapping)
    assert ('"home": "101"' in clv_src or "'home': '101'" in clv_src
            or '"101": "home"' in clv_src or "'101': 'home'" in clv_src), (
        "1x2 decoder must map outcomeId 101 ↔ home (stable across OddsPapi fixtures)"
    )
    assert ('"draw": "102"' in clv_src or "'draw': '102'" in clv_src
            or '"102": "draw"' in clv_src or "'102': 'draw'" in clv_src), (
        "1x2 decoder must map outcomeId 102 ↔ draw"
    )
    assert ('"away": "103"' in clv_src or "'away': '103'" in clv_src
            or '"103": "away"' in clv_src or "'103': 'away'" in clv_src), (
        "1x2 decoder must map outcomeId 103 ↔ away"
    )

    # OU/AH coverage — the lines we actually bet on
    for line_token in ("2.5: 1010", "1.5: 10258", "0.75: 10490"):
        assert line_token in clv_src, f"OU decoder missing line for {line_token}"
    for ah_token in ("0.0: 1072", "-0.5: 1068", "0.5: 1076"):
        assert ah_token in clv_src, f"AH decoder missing line for {ah_token}"

    # Ingest script: dry-run is default; --execute required to write
    assert "--execute" in ing_src, "ingest must require --execute flag to write"
    assert "DRY-RUN" in ing_src, "ingest must print DRY-RUN when not executing"
    assert "is_closing" in ing_src and "Pinnacle" in ing_src, (
        "ingest writes must set bookmaker='Pinnacle' is_closing=true"
    )


@test("COOLBET-MARKET-MIX-AUDIT — audit scripts exist + query simulated_bets by KO hour")
def test_coolbet_market_mix_audit():
    """COOLBET-SEARCH-SPORT-FILTER-FOLLOWUP (2026-06-15): the operator's
    "early-KO matches only have AH/DC" observation was verified — 56% of
    early-KO (00-11 UTC) matches have only AH/DC bets vs 26% for evening-KO.
    Root cause is bot universe (bot_v10_all fires 4× less at early-KO,
    bot_conservative + bot_proven_leagues_v2 produce zero early-KO picks).

    These two diagnostic scripts let the operator re-run the audit any time
    to track whether new bots or v10 retraining shift the early-KO mix:
      - scripts/coolbet_market_mix_audit.py  (pick-hour view + bot universe)
      - scripts/coolbet_early_ko_drilldown.py (KO-hour view + per-match diversity)

    Pin existence + that they query the right tables so a future "let me
    refactor these into one script" change doesn't drop a key axis.
    """
    import pathlib
    a = pathlib.Path("scripts/coolbet_market_mix_audit.py").read_text()
    b = pathlib.Path("scripts/coolbet_early_ko_drilldown.py").read_text()

    # Pick-hour audit must group by EXTRACT(hour FROM created_at) AND market
    assert "EXTRACT(hour FROM created_at)" in a, (
        "market_mix_audit must group picks by created_at hour to test the "
        "cohort-timing hypothesis"
    )
    assert "match_minute_at_pick IS NULL" in a, (
        "market_mix_audit must filter to prematch picks only — in-play picks "
        "have a different cohort timing distribution"
    )
    # Cross-reference with Pinnacle availability so the (c) data-gap hypothesis
    # can be ruled in or out from the same audit output.
    assert "bookmaker = 'Pinnacle'" in a, (
        "market_mix_audit must check Pinnacle availability to test hypothesis (c)"
    )

    # KO-hour drilldown must group by EXTRACT(hour FROM m.date) AND test
    # per-match diversity (the "only AH/DC" claim).
    assert "EXTRACT(hour FROM m.date)" in b, (
        "drilldown must bucket by KO hour (NOT pick-creation hour) to match "
        "the operator's observation pattern"
    )
    assert "asian_handicap" in b and "double_chance" in b, (
        "drilldown must explicitly check for ONLY-AH/DC matches"
    )
    # Per-match diversity check — were there other markets, or is this match
    # genuinely AH/DC-only?
    assert "COUNT(DISTINCT market)" in b, (
        "drilldown must compute distinct-markets-per-match to surface the "
        "diversity-low pattern"
    )


@test("CLV-BACKFILL-FOLLOWUP-A — OP-historical Pinnacle closes flow into Sunday retrain")
def test_clv_backfill_followup_a():
    """CLV-BACKFILL-FOLLOWUP (a) verified 2026-06-15: snapshots written by
    `scripts/ingest_oddspapi_pinnacle_closes.py` (Pinnacle closing odds
    backfilled from OddsPapi /historical-odds) must survive the train.py
    calibration query filters so the Sunday retrain picks them up
    automatically. Verification at the time of shipping confirmed 12,218
    OP-historical rows across 219 matches (2026-04-20 → 2026-06-06) all
    pass — but this smoke pins the contract so a future refactor can't
    silently regress (e.g. by adding a `WHERE source = 'live_pipeline'`
    filter that would exclude OP rows, or a `WHERE minutes_to_kickoff IS
    NULL` filter that would exclude them too since the ingester
    populates minutes_to_kickoff).

    Anti-regression assertions on `workers/model/train.py`:
      • Pinnacle pre-match filter uses ONLY (bookmaker, is_live, timestamp < m.date)
      • Sunday weekly_retrain job still passes --include-pinnacle
      • The ingester sets bookmaker='Pinnacle' is_closing=true is_live default-false
    """
    import pathlib
    train_src = pathlib.Path("workers/model/train.py").read_text()
    sched_src = pathlib.Path("workers/scheduler.py").read_text()
    ing_src   = pathlib.Path("scripts/ingest_oddspapi_pinnacle_closes.py").read_text()

    # The Pinnacle pre-match calibration query (in _load_pinnacle_features)
    # must NOT include a filter that would exclude OP-historical rows.
    # Forbid these patterns specifically — they'd silently break OP backfill:
    forbidden = [
        # Would exclude OP rows (they all have minutes_to_kickoff set by ingester)
        "minutes_to_kickoff IS NULL",
        # Would exclude OP rows (they're all is_closing=true; the train filter
        # picks the LATEST pre-KO snapshot regardless of is_closing flag)
        "AND os.is_closing = false",
        "AND is_closing = false",
        # Would exclude OP rows if a 'source' column ever gets added with
        # different values per pipeline. None today — defensive pin.
        "source = 'live_pipeline'",
        "source = 'live'",
    ]
    for pat in forbidden:
        assert pat not in train_src, (
            f"train.py must not filter out OP-historical rows via `{pat}` — "
            f"CLV-BACKFILL-FOLLOWUP (a) verified OP rows survive the existing "
            f"filters (bookmaker='Pinnacle' AND is_live=false AND timestamp<m.date)"
        )

    # Sunday retrain must still ask for the Pinnacle features
    assert "--include-pinnacle" in sched_src, (
        "weekly_retrain must pass --include-pinnacle so OP-historical Pinnacle "
        "closes feed the model's pinnacle_implied_{home,draw,away} features"
    )

    # Ingester contract — the three flags that make rows pass train's filters
    assert "'Pinnacle'" in ing_src, "ingester must write bookmaker='Pinnacle'"
    assert "is_closing" in ing_src, "ingester must set is_closing column"
    # is_live default=false (from migration 009), inherited by INSERT without explicit value.
    # The ingester's INSERT must NOT set is_live=true, since that would exclude the row
    # from _load_pinnacle_features. Easier to assert that is_live isn't even mentioned.
    assert "is_live=true" not in ing_src and 'is_live, true' not in ing_src.lower(), (
        "ingester must not set is_live=true — would cause _load_pinnacle_features to skip the row"
    )


