@test("TENNIS-ODDS-API-SCANNER — Odds API tennis scanner structure + invariants")
def _():
    """TENNIS-PAPER-BETS Phase 1.3 (2026-06-25): scripts/tennis/odds_api_scanner.py
    is the live tennis value scanner (replaces the OddsPapi-based value_scanner.py
    after the 250 req/mo free tier was busted). Pins the contract:
    - reads OA_KEY or ODDS_API_KEY (matching scheduler env-var convention)
    - hits The Odds API /sports + /sports/{key}/odds endpoints
    - de-vigs Pinnacle for fair odds and uses it as the sharp anchor
    - tunables match the retired scanner so the data history is comparable
    - SOFT_BOOKS excludes betfair_ex_eu (synthetic edges from exchange commission)
      and coolbet (covered by the dedicated 30-min direct scanner)
    - tags rows with src=odds_api in notes so a future swap-back / audit can find them
    """
    import pathlib
    script = pathlib.Path("scripts/tennis/odds_api_scanner.py")
    assert script.exists(), "scripts/tennis/odds_api_scanner.py must exist"
    src = script.read_text()
    # entry points
    for fn in ["list_active_tennis_sports", "extract_book_prices", "devig_two_way",
               "kelly_stake", "scan_sport", "upsert_fixture_today", "insert_value_bet"]:
        assert f"def {fn}" in src, f"{fn} must be defined"
    # provider + auth
    assert "api.the-odds-api.com/v4" in src, "must hit The Odds API v4"
    assert 'OA_KEY' in src and 'ODDS_API_KEY' in src, (
        "must accept either OA_KEY or ODDS_API_KEY (matches scheduler convention)"
    )
    # sharp + soft book registry
    assert 'SHARP_BOOK = "pinnacle"' in src, "Pinnacle must be the sharp anchor"
    assert '"bet365"' in src and '"unibet_eu"' in src and '"williamhill"' in src, (
        "SOFT_BOOKS must include the core soft books we scan against"
    )
    assert '"betfair_ex_eu"' not in src.split("SOFT_BOOKS")[1].split("]")[0], (
        "betfair_ex_eu must NOT be in SOFT_BOOKS — exchange odds produce synthetic "
        "edges that get eaten by Betfair commission; would pollute training data"
    )
    assert '"coolbet"' not in src.split("SOFT_BOOKS")[1].split("]")[0], (
        "coolbet must NOT be in SOFT_BOOKS — covered by the dedicated 30-min direct "
        "scanner; including here would waste Odds API credits on duplicate data"
    )
    # tunables that pin scanner behavior (must stay aligned with paper-bet history)
    for k in ("RECORD_MIN_EDGE", "DISPLAY_MIN_EDGE", "MAX_CREDIBLE_EDGE",
              "KELLY_FRAC", "MAX_STAKE"):
        assert k in src, f"{k} constant must be defined"
    # writes to tennis_value_bets with provider tag
    assert "INSERT INTO tennis_value_bets" in src, "must INSERT into tennis_value_bets"
    assert "src=odds_api" in src, "rows must be tagged 'src=odds_api' in notes for traceability"
    # migration sanity (table contract)
    migration = pathlib.Path("supabase/migrations/190_tennis_value_bets.sql")
    assert migration.exists(), "190_tennis_value_bets.sql migration must exist"
    msrc = migration.read_text()
    assert "tennis_value_bets" in msrc and "pin_fair_odds" in msrc and "edge_pct" in msrc


@test("TENNIS-SETTLEMENT — Odds API settlement job + scheduler hooks")
def _():
    """TENNIS-PAPER-BETS Phase 1.4 (2026-06-25): settlement closes the loop on
    tennis_value_bets rows by calling The Odds API /scores per active sport.
    Pins:
    - scripts/tennis/settle_value_bets.py exists with the entry points
    - derive_winner handles the score comparison
    - cheap pre-check skips /scores fetches when nothing past kickoff+2h
      (prevents burning credits on idle runs)
    - rows match by fixture_id (= Odds API event id) NOT player-name fuzzy match
    - void/win/loss are the only result values written
    - scheduler.py declares job_tennis_settlement and registers BOTH cron slots
    """
    import pathlib
    script = pathlib.Path("scripts/tennis/settle_value_bets.py")
    assert script.exists(), "scripts/tennis/settle_value_bets.py must exist"
    src = script.read_text()

    for fn in ["list_active_tennis_sports", "derive_winner", "settle_event",
               "settle_sport"]:
        assert f"def {fn}" in src, f"{fn} must be defined"

    assert "api.the-odds-api.com/v4" in src, "must hit The Odds API"
    assert "/scores" in src, "must call /scores endpoint"
    assert 'OA_KEY' in src and 'ODDS_API_KEY' in src, (
        "must accept either OA_KEY or ODDS_API_KEY (matches scheduler convention)"
    )

    # Cheap pre-check — don't burn credits if nothing's pending
    assert "kickoff_time < now() - interval '2 hours'" in src, (
        "must skip /scores fetches when no row is past kickoff+2h "
        "(prevents wasting credits on idle runs)"
    )
    assert "Nothing to settle" in src, "pre-check must short-circuit visibly"

    # fixture_id is THE join — never re-resolve via player names (fuzzy matching
    # was the source of the TENNIS-MATCH-FIXTURE-QUALITY bug class)
    assert "WHERE fixture_id = %s" in src, (
        "must match unsettled rows by fixture_id (= Odds API event id), "
        "NOT by player name (fuzzy matching is the TENNIS-MATCH-FIXTURE-QUALITY bug class)"
    )

    # The only three result values the settlement writes
    for v in ("'win'", "'loss'", "'void'"):
        assert v in src, f"settlement must write {v} result"

    # PnL formula sanity — stake * (book_odds - 1) on win, -stake on loss
    assert "(float(row[\"book_odds\"]) - 1.0)" in src, (
        "win pnl must be stake * (book_odds - 1.0)"
    )

    # Scheduler wiring
    sched_src = pathlib.Path("workers/scheduler.py").read_text()
    assert "def job_tennis_settlement" in sched_src, (
        "scheduler must declare job_tennis_settlement"
    )
    assert "scripts/tennis/settle_value_bets.py" in sched_src, (
        "job must shell out to scripts/tennis/settle_value_bets.py"
    )
    assert 'id="tennis_settlement_night"' in sched_src, (
        "scheduler must register the night settlement cron"
    )
    assert 'id="tennis_settlement_afternoon"' in sched_src, (
        "scheduler must register the afternoon settlement cron"
    )


@test("TENNIS-BOTS-CONFIG — bot registry + matching_bots logic + scanner routing + migration")
def _():
    """TENNIS-PAPER-BETS Phase 2 (2026-06-25): observations from the scanners
    now route through scripts/tennis/bots_config.py to produce one row per
    (bot, fixture, bookmaker, selection, scan_date) tuple. Pins:

    - Three starter bots: bot_tennis_pin_broad (≥3% any book),
      bot_tennis_pin_selective (≥5% any book), bot_tennis_coolbet_only
      (≥3% Coolbet only). Reorder/rename = explicit decision, not accidental.
    - matching_bots() math is correct (boundary cases: at-threshold edges
      qualify, below-threshold don't; bookmaker whitelist enforced)
    - odds_api_scanner.py + place_coolbet_tennis.py both import + use the
      bot config (no copy-pasted parallel logic)
    - Migration 261 widens unique index to include bot_id (otherwise
      multiple bot rows for the same fixture-book-selection would collide)
    - tennis_value_bets.bot_id column added with legacy_unsegmented backfill
    """
    import pathlib, sys
    sys.path.insert(0, ".")

    from scripts.tennis.bots_config import TENNIS_BOTS, matching_bots
    assert set(TENNIS_BOTS) == {
        "bot_tennis_pin_broad",
        "bot_tennis_pin_selective",
        "bot_tennis_coolbet_only",
    }, f"unexpected bot set: {list(TENNIS_BOTS)}"

    assert TENNIS_BOTS["bot_tennis_pin_broad"]["edge_threshold"] == 0.03
    assert TENNIS_BOTS["bot_tennis_pin_selective"]["edge_threshold"] == 0.05
    assert TENNIS_BOTS["bot_tennis_coolbet_only"]["edge_threshold"] == 0.03
    assert TENNIS_BOTS["bot_tennis_coolbet_only"]["bookmakers"] == ["coolbet"]
    assert TENNIS_BOTS["bot_tennis_pin_broad"]["bookmakers"] is None
    assert TENNIS_BOTS["bot_tennis_pin_selective"]["bookmakers"] is None

    coolbet_4pct = [b for b, _ in matching_bots(bookmaker="coolbet", edge=0.04)]
    assert set(coolbet_4pct) == {"bot_tennis_pin_broad", "bot_tennis_coolbet_only"}
    bet365_6pct = [b for b, _ in matching_bots(bookmaker="bet365", edge=0.06)]
    assert set(bet365_6pct) == {"bot_tennis_pin_broad", "bot_tennis_pin_selective"}
    assert not list(matching_bots(bookmaker="bet365", edge=0.02))
    coolbet_8pct = [b for b, _ in matching_bots(bookmaker="coolbet", edge=0.08)]
    assert set(coolbet_8pct) == set(TENNIS_BOTS)
    assert "bot_tennis_pin_broad" in [b for b, _ in matching_bots(bookmaker="bet365", edge=0.03)]
    assert "bot_tennis_pin_selective" in [b for b, _ in matching_bots(bookmaker="bet365", edge=0.05)]

    odds_api_src = pathlib.Path("scripts/tennis/odds_api_scanner.py").read_text()
    assert "from scripts.tennis.bots_config import matching_bots" in odds_api_src
    assert "matching_bots(bookmaker=" in odds_api_src
    assert "bot_id" in odds_api_src and "%(bot_id)s" in odds_api_src
    assert "(fixture_id, bookmaker, selection, scan_date, bot_id)" in odds_api_src

    coolbet_src = pathlib.Path("scripts/tennis/place_coolbet_tennis.py").read_text()
    assert "from scripts.tennis.bots_config import matching_bots" in coolbet_src
    assert 'matching_bots(bookmaker="coolbet"' in coolbet_src
    assert "(fixture_id, bookmaker, selection, scan_date, bot_id)" in coolbet_src

    mig = pathlib.Path("supabase/migrations/261_tennis_bot_segmentation.sql").read_text()
    assert "ADD COLUMN IF NOT EXISTS bot_id text" in mig
    assert "legacy_unsegmented" in mig
    assert "DROP INDEX IF EXISTS tennis_value_bets_unique" in mig
    assert "(fixture_id, bookmaker, selection, scan_date, bot_id)" in mig


@test("TENNIS-VOLUME-ACCUMULATION — Coolbet-only observations + fair_source + migration 263")
def _():
    """TENNIS-PAPER-BETS Phase 4 (2026-06-25): the Coolbet scanner writes a row
    for every Coolbet tennis match — including Challenger/ITF/Futures that
    have no Pinnacle reference in tennis_fixtures_today. The Pinnacle close +
    match result get backfilled later from tennis-data.co.uk weekly CSVs.

    The mental model shift: tennis_value_bets is no longer just actionable
    paper-bets — it's also a training-data pond of every match Coolbet exposes.
    The `fair_source` column (added in migration 263) separates the two:
      - 'odds_api_pinnacle' — actionable picks with edge/CLV calculations
      - 'coolbet_only'      — observations awaiting CSV backfill

    Pins:
    - Migration 263: pin_fair_odds + edge_pct become NULLable; fair_source
      column added, NOT NULL with default 'unknown'; existing rows backfilled
      to 'odds_api_pinnacle'
    - Coolbet scanner has a Coolbet-only write path: when match_to_fixture
      returns None, writes a row anyway with fair_source='coolbet_only',
      bot_id='observation_unevaluated', pin_fair_odds/edge_pct NULL,
      fixture_id prefixed 'coolbet:' to distinguish from Odds API event_ids
    - Odds API scanner explicitly sets fair_source='odds_api_pinnacle' on
      INSERT (without this, new rows would default to 'unknown')
    - Closing-odds capture restricts to fair_source='odds_api_pinnacle' so
      it doesn't waste credits trying to /odds fetch Coolbet-only fixtures
      whose IDs The Odds API can't resolve
    """
    import pathlib

    mig = pathlib.Path("supabase/migrations/264_tennis_volume_accumulation.sql").read_text()
    assert "ALTER COLUMN pin_fair_odds DROP NOT NULL" in mig, (
        "migration must make pin_fair_odds NULLable for Coolbet-only rows"
    )
    assert "ALTER COLUMN edge_pct DROP NOT NULL" in mig, (
        "migration must make edge_pct NULLable (no edge w/o Pinnacle reference)"
    )
    assert "ADD COLUMN IF NOT EXISTS fair_source text" in mig, (
        "migration must add fair_source column"
    )
    assert "ALTER COLUMN fair_source SET NOT NULL" in mig, (
        "fair_source must end up NOT NULL after backfill"
    )
    assert "'odds_api_pinnacle'" in mig, (
        "migration must backfill existing rows with fair_source='odds_api_pinnacle'"
    )

    coolbet_src = pathlib.Path("scripts/tennis/place_coolbet_tennis.py").read_text()
    # Coolbet scanner must have both paths
    assert "'odds_api_pinnacle'" in coolbet_src, (
        "Pinnacle-anchored path must explicitly tag fair_source='odds_api_pinnacle'"
    )
    assert "'coolbet_only'" in coolbet_src, (
        "Coolbet-only path must tag fair_source='coolbet_only'"
    )
    assert "'observation_unevaluated'" in coolbet_src, (
        "Coolbet-only rows must use bot_id='observation_unevaluated' (single bucket, "
        "not a per-edge bot match — edge is unknown until CSV backfill)"
    )
    # Coolbet-only fixture_id prefix
    assert '"coolbet:' in coolbet_src, (
        "Coolbet-only rows must use 'coolbet:<id>' fixture_id prefix to avoid "
        "collisions with Odds API event_ids during settlement"
    )
    # Tag-and-record path: notes must carry the league name for downstream backfill matching
    assert "no_pin_anchor" in coolbet_src, (
        "Coolbet-only notes must include 'no_pin_anchor' marker for backfill scripts"
    )

    odds_api_src = pathlib.Path("scripts/tennis/odds_api_scanner.py").read_text()
    assert "'odds_api_pinnacle'" in odds_api_src, (
        "Odds API scanner INSERT must explicitly set fair_source='odds_api_pinnacle' "
        "(otherwise new rows would default to 'unknown')"
    )

    closing_src = pathlib.Path("scripts/tennis/capture_closing_odds.py").read_text()
    assert "fair_source = 'odds_api_pinnacle'" in closing_src, (
        "closing-odds imminent query must restrict to fair_source='odds_api_pinnacle' "
        "so it doesn't waste credits on Coolbet-only fixtures whose IDs The Odds API "
        "can't resolve"
    )


@test("TENNIS-HEALTH-ALERTS — scanner-silent + settlement-stale tripwires + runner wiring")
def _():
    """TENNIS-PAPER-BETS Phase 3 (2026-06-25): two tripwires for silent
    failures. Pins:

    - check_tennis_scanner_silent: alerts if last successful tennis_scanner
      pipeline_runs row > 12h ago. This is the exact failure mode that bit
      OddsPapi (tennis_value_bets was empty for ~a week, no alert) — would
      have caught it within 12h.
    - check_tennis_settlement_stale: alerts if > 5 tennis_value_bets rows
      past kickoff+6h still have result=NULL. Threshold low enough that one
      stuck tournament triggers, high enough that occasional walkovers don't.
    - Both wired into the existing morning + settlement runners (no new
      scheduler entries; piggybacks on 09:35 + 21:30 UTC slots that already
      run the soccer health checks).
    """
    import pathlib, re
    src = pathlib.Path("workers/jobs/health_alerts.py").read_text()

    assert "def check_tennis_scanner_silent" in src, (
        "check_tennis_scanner_silent must be defined"
    )
    assert "def check_tennis_settlement_stale" in src, (
        "check_tennis_settlement_stale must be defined"
    )

    # Scanner-silent contract
    assert "job_name = 'tennis_scanner'" in src and "status   = 'completed'" in src, (
        "scanner-silent check must query pipeline_runs for job='tennis_scanner' "
        "AND status='completed' (max started_at = last success)"
    )
    assert "if age_hours > 12" in src, (
        "scanner-silent threshold must be 12 hours (between consecutive 06+14 UTC scanner runs)"
    )
    assert '"tennis_scanner_silent"' in src, (
        "scanner-silent must use 'tennis_scanner_silent' as the dedup key"
    )

    # Settlement-stale contract
    assert "FROM tennis_value_bets" in src and "result IS NULL" in src, (
        "settlement-stale must query tennis_value_bets WHERE result IS NULL"
    )
    assert "kickoff_time < %s" in src, (
        "settlement-stale must filter on kickoff_time past cutoff"
    )
    # Threshold + cutoff
    assert "STALE_THRESHOLD = 5" in src, (
        "settlement-stale threshold must be 5 (small enough one stuck tournament fires)"
    )
    assert "timedelta(hours=6)" in src, (
        "settlement-stale cutoff must be kickoff + 6h"
    )

    # Runner wiring — both checks called inside the existing runners
    # (don't add a third scheduler entry)
    assert re.search(
        r"def run_morning_checks.*?check_tennis_scanner_silent\(\)",
        src, re.DOTALL,
    ), "run_morning_checks must call check_tennis_scanner_silent()"
    assert re.search(
        r"def run_settlement_check.*?check_tennis_settlement_stale\(\)",
        src, re.DOTALL,
    ), "run_settlement_check must call check_tennis_settlement_stale()"


@test("TENNIS-CLOSING-ODDS — Pinnacle closing snap + CLV computation + scheduler hook")
def _():
    """TENNIS-PAPER-BETS Phase 1.5 (2026-06-25): every 30 min during tennis
    hours, capture Pinnacle h2h price for value-bet rows with kickoff in the
    next 45 min, write to closing_odds + compute clv = book_odds/close - 1.
    Pins:
    - scripts/tennis/capture_closing_odds.py exists with the entry points
    - find_imminent_fixtures reads from tennis_value_bets (NOT tennis_fixtures_today)
      — this is the cost-saving choice; reading from fixtures table would burn
      credits on sports with no rows needing CLV
    - filter is `result IS NULL` only (NOT `closing_odds IS NULL`) — every
      cron run within the window re-captures and overwrites so the final
      stored value is the closest-to-kickoff Pinnacle snap. Credit cost is
      per-sport per-fire, not per-row, so re-capturing is free.
    - update overwrites closing_odds on every call — later captures (closer
      to kickoff) replace earlier ones; the final stored value is the
      closest-to-kickoff Pinnacle snap
    - scheduler.py declares job_tennis_closing_odds + registers 30-min cron
    """
    import pathlib
    script = pathlib.Path("scripts/tennis/capture_closing_odds.py")
    assert script.exists(), "scripts/tennis/capture_closing_odds.py must exist"
    src = script.read_text()

    for fn in ["list_active_tennis_sport_map", "find_imminent_fixtures",
               "extract_pinnacle_h2h", "update_closing_for_fixture"]:
        assert f"def {fn}" in src, f"{fn} must be defined"

    assert "api.the-odds-api.com/v4" in src, "must hit The Odds API"
    assert 'OA_KEY' in src and 'ODDS_API_KEY' in src, (
        "must accept either OA_KEY or ODDS_API_KEY (matches scheduler convention)"
    )
    assert 'bookmakers="pinnacle"' in src, (
        "must request only Pinnacle from /odds (sharp anchor, no soft books needed)"
    )

    # The cost-saving choice — read from tennis_value_bets, not tennis_fixtures_today
    assert "FROM tennis_value_bets" in src, (
        "find_imminent_fixtures must read from tennis_value_bets so we only "
        "burn credits on sports with rows actually needing CLV"
    )
    # NOTE: explicitly NOT filtering on closing_odds IS NULL — see
    # find_imminent_fixtures docstring for why (re-capture for closer-to-close
    # snap, free since credit cost is per-sport).
    assert "result IS NULL" in src, (
        "imminent query must filter to unsettled rows"
    )

    # Pre-check: if nothing imminent, skip the /sports call too
    assert "Nothing imminent" in src, (
        "must short-circuit visibly when no rows are imminent (saves /sports credit too)"
    )

    # CLV formula sanity
    assert "(book_odds / %s::numeric) - 1" in src, (
        "CLV formula must be (book_odds / closing_odds) - 1"
    )

    # Scheduler wiring
    sched_src = pathlib.Path("workers/scheduler.py").read_text()
    assert "def job_tennis_closing_odds" in sched_src, (
        "scheduler must declare job_tennis_closing_odds"
    )
    assert "scripts/tennis/capture_closing_odds.py" in sched_src, (
        "scheduler must shell out to scripts/tennis/capture_closing_odds.py"
    )
    assert 'id="tennis_closing_odds"' in sched_src, (
        "scheduler must register the closing-odds cron"
    )
    # 30-min cadence in tennis hours
    assert 'minute="0,30"' in sched_src and 'hour="6-22"' in sched_src, (
        "cron must fire every 30 min during 06-22 UTC tennis window"
    )


