@test("CS2-BOT-CONSENSUS — soccer-pattern + outlier guard + per-pick UNIQUE")
def _():
    """Migration 210 + bot now fires one pick per (match,market,side) at best book,
    with market-consensus outlier guard."""
    import pathlib, importlib.util
    mig = pathlib.Path("supabase/migrations/210_cs2_bot_clv.sql").read_text()
    assert "cs2_simulated_bets_per_pick_key" in mig
    assert "UNIQUE (bot_name, bo3gg_id, market, pick)" in mig
    for col in ["closing_odds_at_kickoff", "closing_odds_snapshot_at", "clv",
                "consensus_implied_prob", "n_books_at_pick"]:
        assert col in mig, f"migration 210 missing column {col}"

    p = pathlib.Path("scripts/esports/cs2_bot.py")
    src = p.read_text()
    # MIN_BOOKS_FOR_PICK default relaxed 2→1 in 2026-06-25 CS2-MIN-BOOKS-RELAX
    # to unblock supply (only ~9% of CS2 matches had ≥2 books). The 4
    # canonical bots opt back up to 2 via cfg override — see CS2-BOT-MIN-BOOKS-RELAX.
    assert "MIN_BOOKS_FOR_PICK = 1" in src
    assert "MAX_CONSENSUS_DRIFT = 0.30" in src
    assert "def market_consensus" in src
    assert "def _consider_side" in src
    assert "def _eligible_books" in src
    # ON CONFLICT now matches the new UNIQUE
    assert "ON CONFLICT (bot_name, bo3gg_id, market, pick) DO NOTHING" in src

    spec = importlib.util.spec_from_file_location("cs2_bot", p)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    # Consensus math
    res = mod.market_consensus([("a", 3.06), ("b", 3.40)])
    assert res is not None
    cons_prob, cons_odds = res
    assert 3.10 < cons_odds < 3.30
    # Outlier rejected
    pick = mod._consider_side(
        source="elo+pq_v1", side="team1", team_name="X",
        prices=[("bo3gg", 1.40), ("coolbet", 5.00)],   # coolbet wildly above consensus
        fair=2.0, thr=1.90, prob=0.55, min_extra=0.05,
    )
    assert pick is None, "30%+ consensus outlier must be rejected"
    # Acceptable case
    pick = mod._consider_side(
        source="elo+pq_v1", side="team1", team_name="X",
        prices=[("bo3gg", 2.30), ("coolbet", 2.40)],
        fair=2.0, thr=1.90, prob=0.55, min_extra=0.05,
    )
    assert pick is not None and pick["bookie"] == "coolbet"
    # Single book is now accepted by default (MIN_BOOKS_FOR_PICK=1) but
    # rejected when the caller demands a 2-book consensus (as the 4
    # canonical baseline bots do via cfg override — see CS2-BOT-MIN-BOOKS-RELAX).
    pick = mod._consider_side(
        source="elo+pq_v1", side="team1", team_name="X",
        prices=[("bo3gg", 2.30)],
        fair=2.0, thr=1.90, prob=0.55, min_extra=0.05,
        min_books=2,
    )
    assert pick is None, "with min_books=2, single-book quote must be rejected"
    # Same single-book input WITH the relaxed default (min_books=1) fires:
    pick = mod._consider_side(
        source="elo+pq_v1", side="team1", team_name="X",
        prices=[("bo3gg", 2.30)],
        fair=2.0, thr=1.90, prob=0.55, min_extra=0.05,
        min_books=1,
    )
    assert pick is not None and pick["bookie"] == "bo3gg", (
        "with min_books=1, single-book quote must fire on edge"
    )

    # CRAZY edge: aAa vs RUSTEC type. Books agree aAa is 17-20%, model says 39%.
    # Threshold derived from 39% = 2.56, books offer 5.80. edge = +127% (over MAX_EXTRA_EDGE).
    pick = mod._consider_side(
        source="hltv_v1", side="team1", team_name="aAa",
        prices=[("bo3gg", 5.80), ("coolbet", 5.00)],
        fair=2.56, thr=2.43, prob=0.39, min_extra=0.03,
    )
    assert pick is None, "edge over 50% must be killed (or model-vs-consensus divergence)"

    # Wide model-vs-consensus divergence even with small edge — kill
    pick = mod._consider_side(
        source="hltv_v1", side="team1", team_name="X",
        prices=[("bo3gg", 2.50), ("coolbet", 2.55)],
        fair=2.0, thr=1.90, prob=0.70,   # we say 70%, market says ~40%
        min_extra=0.05,
    )
    assert pick is None, "model vs consensus 30pp apart must be killed"


